set search_path=thue,public;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu20$md$,$md$TNCN_109-2025$md$,$md$Điều 20. Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh
1. Thuế thu nhập cá nhân đối với thu nhập từ kinh doanh của cá nhân không
cư trú được xác định bằng doanh thu từ hoạt động kinh doanh quy định tại khoản
2 Điều này nhân (x) với thuế suất quy định tại khoản 3 Điều này.
2. Doanh thu là toàn bộ tiền bán hàng, tiền gia công, tiền cung ứng dịch vụ
kể cả trợ giá, phụ thu, phụ trội mà cá nhân được hưởng, không phân biệt đã thu
được tiền hay chưa thu được tiền, bao gồm cả chi phí do bên mua hàng hoá, dịch
vụ trả thay cho cá nhân không cư trú mà không được hoàn trả.
Trường hợp thoả thuận hợp đồng không bao gồm thuế thu nhập cá nhân thì
doanh thu tính thuế phải quy đổi là toàn bộ số tiền mà cá nhân không cư trú nhận
được dưới bất kỳ hình thức nào từ việc cung cấp hàng hoá, dịch vụ tại Việt Nam
không phụ thuộc vào địa điểm tiến hành các hoạt động kinh doanh.
3. Thuế suất:
a) Phân phối, cung cấp hàng hoá: 1%;
b) Dịch vụ, xây dựng không bao thầu nguyên vật liệu: 5%;
c) Sản xuất, vận tải, dịch vụ có gắn với hàng hoá, xây dựng có bao thầu
nguyên vật liệu: 2%;
d) Hoạt động cung cấp sản phẩm và dịch vụ nội dung thông tin số về giải
trí, trò chơi điện tử, phim số, ảnh số, nhạc số, quảng cáo: 5%;
đ) Hoạt động kinh doanh khác: 2%.$md$,$md$TNCN_109-2025_ChươngIII$md$,20,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu21$md$,$md$TNCN_109-2025$md$,$md$Điều 21. Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công
Thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công của cá nhân
không cư trú được xác định bằng tổng số tiền lương, tiền công mà cá nhân không

cư trú nhận được do thực hiện công việc tại Việt Nam nhân (x) với thuế suất 20%,
không phân biệt nơi trả thu nhập.$md$,$md$TNCN_109-2025_ChươngIII$md$,21,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu22$md$,$md$TNCN_109-2025$md$,$md$Điều 22. Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn
Thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn của cá nhân không
cư trú được xác định bằng tổng số thu nhập mà cá nhân không cư trú nhận được
từ việc đầu tư vốn vào tổ chức, cá nhân tại Việt Nam nhân (x) với thuế suất 5%.$md$,$md$TNCN_109-2025_ChươngIII$md$,22,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu23$md$,$md$TNCN_109-2025$md$,$md$Điều 23. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn
1. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng vốn của cá
nhân không cư trú được xác định bằng thu nhập tính thuế nhân (x) với thuế suất
20% theo từng lần phát sinh, không phân biệt việc chuyển nhượng được thực hiện
tại Việt Nam hay tại nước ngoài. Trong đó, thu nhập tính thuế từ chuyển nhượng
vốn được xác định bằng giá chuyển nhượng trừ (-) đi giá mua và các khoản chi
phí hợp lý liên quan đến việc tạo ra thu nhập từ chuyển nhượng phần vốn tại tổ
chức, cá nhân Việt Nam.
Trường hợp không xác định được giá mua và các chi phí liên quan đến việc
chuyển nhượng vốn thì thuế thu nhập cá nhân được xác định bằng giá chuyển
nhượng phần vốn tại tổ chức, cá nhân Việt Nam nhân (x) với thuế suất 2%.
2. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng chứng khoán
của cá nhân không cư trú được xác định bằng giá chuyển nhượng nhân (x) với
thuế suất 0,1%.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngIII$md$,23,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu24$md$,$md$TNCN_109-2025$md$,$md$Điều 24. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng
bất động sản
1. Thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng bất động sản
của cá nhân không cư trú được xác định bằng giá chuyển nhượng nhân (x) với
thuế suất 2%.
2. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngIII$md$,24,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu25$md$,$md$TNCN_109-2025$md$,$md$Điều 25. Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền,$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền,
nhượng quyền thương mại
1. Thuế thu nhập cá nhân đối với thu nhập từ tiền bản quyền của cá nhân
không cư trú được xác định bằng phần thu nhập vượt trên 20 triệu đồng theo từng
hợp đồng chuyển giao, chuyển quyền sử dụng các đối tượng của quyền sở hữu trí
tuệ, chuyển giao công nghệ tại Việt Nam nhân (x) với thuế suất 5%.
2. Thuế thu nhập cá nhân đối với thu nhập từ nhượng quyền thương mại
của cá nhân không cư trú được xác định bằng phần thu nhập vượt trên 20 triệu
đồng theo từng hợp đồng nhượng quyền thương mại tại Việt Nam nhân (x) với
thuế suất 5%.$md$,$md$TNCN_109-2025_ChươngIII$md$,25,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu26$md$,$md$TNCN_109-2025$md$,$md$Điều 26. Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng,$md$,$md$Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng,
nhận thừa kế, quà tặng
Thuế thu nhập cá nhân đối với thu nhập từ trúng thưởng, nhận thừa kế, quà
tặng của cá nhân không cư trú được xác định bằng phần giá trị vượt trên 20 triệu
đồng theo từng lần trúng thưởng, nhận thừa kế, quà tặng tại Việt Nam nhân (x)
với thuế suất 10%.$md$,$md$TNCN_109-2025_ChươngIII$md$,26,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu27$md$,$md$TNCN_109-2025$md$,$md$Điều 27. Thuế thu nhập cá nhân đối với thu nhập khác$md$,$md$Thuế thu nhập cá nhân đối với thu nhập khác
1. Thuế thu nhập cá nhân đối với thu nhập khác của cá nhân không cư trú
quy định tại các điểm a, b và c khoản 10 Điều 3 của Luật này được xác định
bằng thu nhập tính thuế nhân (x) với thuế suất 5%. Thu nhập tính thuế là phần
thu nhập vượt trên 20 triệu đồng mà người nộp thuế nhận được theo từng lần
phát sinh.
2. Thuế thu nhập cá nhân đối với thu nhập khác của cá nhân không cư trú
quy định tại điểm d và điểm đ khoản 10 Điều 3 của Luật này được xác định bằng
giá chuyển nhượng nhân (x) với thuế suất 0,1%.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$TNCN_109-2025_ChươngIII$md$,27,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu28$md$,$md$TNCN_109-2025$md$,$md$Điều 28. Thời điểm xác định thu nhập tính thuế$md$,$md$Thời điểm xác định thu nhập tính thuế
1. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại Điều
20 của Luật này là thời điểm cá nhân không cư trú nhận được thu nhập hoặc thời
điểm xuất hoá đơn bán hàng hoá, cung cấp dịch vụ.
2. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại các
điều 21, 22, 25, 26 và 27 của Luật này là thời điểm tổ chức, cá nhân tại Việt Nam
trả thu nhập cho cá nhân không cư trú hoặc thời điểm cá nhân không cư trú nhận
được thu nhập.
3. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại Điều
23 của Luật này là thời điểm giao dịch hoàn thành theo quy định của pháp luật.
4. Thời điểm xác định thu nhập tính thuế đối với thu nhập quy định tại Điều
24 của Luật này là thời điểm hợp đồng chuyển nhượng có hiệu lực theo quy định
của pháp luật hoặc thời điểm đăng ký quyền sử dụng, quyền sở hữu bất động sản.
5. Chính phủ quy định chi tiết Điều này.
ĐIỀU KHOẢN THI HÀNH$md$,$md$TNCN_109-2025_ChươngIII$md$,28,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$TNCN_109-2025_Dieu29$md$,$md$TNCN_109-2025$md$,$md$Điều 29. Hiệu lực thi hành$md$,$md$Hiệu lực thi hành
1. Luật này có hiệu lực thi hành từ ngày 01 tháng 7 năm 2026, trừ trường
hợp quy định tại khoản 2 Điều này.

2. Các quy định liên quan đến thu nhập từ kinh doanh, từ tiền lương, tiền
công của cá nhân cư trú áp dụng từ kỳ tính thuế năm 2026.
3. Luật Thuế thu nhập cá nhân số 04/2007/QH12 đã được sửa đổi, bổ sung
một số điều theo Luật số 26/2012/QH13, Luật số 71/2014/QH13, Luật số
31/2024/QH15, Luật số 43/2024/QH15, Luật số 48/2024/QH15, Luật số
56/2025/QH15, Luật số 71/2025/QH15 và Luật số 93/2025/QH15 hết hiệu lực kể từ
ngày Luật này có hiệu lực thi hành; riêng các quy định liên quan đến thu nhập từ
kinh doanh, từ tiền lương, tiền công của cá nhân cư trú hết hiệu lực thi hành từ kỳ
tính thuế năm 2026.
4. Trường hợp có quy định khác nhau về ưu đãi thuế giữa Luật này với
Luật Thủ đô, nghị quyết của Quốc hội và giải pháp quy định tại điểm h khoản 8
Điều 10 của Luật Tổ chức Chính phủ thì áp dụng theo quy định của Luật Thủ đô,
nghị quyết của Quốc hội và giải pháp quy định tại điểm h khoản 8 Điều 10 của
Luật Tổ chức Chính phủ. Trường hợp quy định tại Luật này ưu đãi hơn thì người
nộp thuế được lựa chọn áp dụng mức ưu đãi có lợi nhất.
Luật này được Quốc hội nước Cộng hòa xã hội chủ nghĩa Việt Nam khóa XV,
Kỳ họp thứ 10 thông qua ngày 10 tháng 12 năm 2025.
CHỦ TỊCH QUỐC HỘI
Trần Thanh Mẫn$md$,$md$TNCN_109-2025_ChươngIV$md$,29,$md$2026-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu1$md$,$md$GTGT_48-2024$md$,$md$Điều 1. Phạm vi điều chỉnh$md$,$md$Phạm vi điều chỉnh
Luật này quy định về đối tượng chịu thuế, đối tượng không chịu thuế, người
nộp thuế, căn cứ và phương pháp tính thuế, khấu trừ và hoàn thuế giá trị gia tăng.$md$,$md$GTGT_48-2024_ChươngI$md$,1,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu2$md$,$md$GTGT_48-2024$md$,$md$Điều 2. Thuế giá trị gia tăng$md$,$md$Thuế giá trị gia tăng
Thuế giá trị gia tăng là thuế tính trên giá trị tăng thêm của hàng hóa, dịch vụ
phát sinh trong quá trình từ sản xuất, lưu thông đến tiêu dùng.$md$,$md$GTGT_48-2024_ChươngI$md$,2,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu3$md$,$md$GTGT_48-2024$md$,$md$Điều 3. Đối tượng chịu thuế$md$,$md$Đối tượng chịu thuế
Hàng hóa, dịch vụ sử dụng cho sản xuất, kinh doanh và tiêu dùng ở Việt Nam
là đối tượng chịu thuế giá trị gia tăng, trừ các đối tượng quy định tại Điều 5 của
Luật này.$md$,$md$GTGT_48-2024_ChươngI$md$,3,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu4$md$,$md$GTGT_48-2024$md$,$md$Điều 4. Người nộp thuế$md$,$md$Người nộp thuế
1. Tổ chức, hộ, cá nhân sản xuất, kinh doanh hàng hóa, dịch vụ chịu thuế giá
trị gia tăng (sau đây gọi là cơ sở kinh doanh).
2. Tổ chức, cá nhân nhập khẩu hàng hóa chịu thuế giá trị gia tăng (sau đây gọi
là người nhập khẩu).
3. Tổ chức, cá nhân sản xuất, kinh doanh tại Việt Nam mua dịch vụ (kể cả
trường hợp mua dịch vụ gắn với hàng hóa) của tổ chức nước ngoài không có cơ sở
thường trú tại Việt Nam, cá nhân ở nước ngoài là đối tượng không cư trú tại
Việt Nam, trừ trường hợp quy định tại khoản 4 và khoản 5 Điều này; tổ chức sản
xuất, kinh doanh tại Việt Nam mua hàng hóa, dịch vụ để tiến hành hoạt động tìm
kiếm thăm dò, phát triển mỏ dầu khí và khai thác dầu khí của tổ chức nước ngoài
không có cơ sở thường trú tại Việt Nam, cá nhân ở nước ngoài là đối tượng không
cư trú tại Việt Nam.

4. Nhà cung cấp nước ngoài không có cơ sở thường trú tại Việt Nam có hoạt
động kinh doanh thương mại điện tử, kinh doanh dựa trên nền tảng số với tổ chức,
cá nhân tại Việt Nam (sau đây gọi là nhà cung cấp nước ngoài); tổ chức là nhà
quản lý nền tảng số nước ngoài thực hiện khấu trừ, nộp thay nghĩa vụ thuế phải
nộp của nhà cung cấp nước ngoài; tổ chức kinh doanh tại Việt Nam áp dụng
phương pháp tính thuế giá trị gia tăng là phương pháp khấu trừ thuế mua dịch vụ
của nhà cung cấp nước ngoài không có cơ sở thường trú tại Việt Nam thông qua
kênh thương mại điện tử hoặc các nền tảng số thực hiện khấu trừ, nộp thay nghĩa
vụ thuế phải nộp của nhà cung cấp nước ngoài.
5. Tổ chức là nhà quản lý sàn giao dịch thương mại điện tử, nhà quản lý nền
tảng số có chức năng thanh toán thực hiện khấu trừ, nộp thuế thay, kê khai số thuế
đã khấu trừ cho hộ kinh doanh, cá nhân kinh doanh trên sàn thương mại điện tử,
nền tảng số.
6. Chính phủ quy định chi tiết các khoản 1, 4 và 5 Điều này; quy định về người
nộp thuế trong trường hợp nhà cung cấp nước ngoài cung cấp dịch vụ cho người
mua là tổ chức kinh doanh tại Việt Nam áp dụng phương pháp khấu trừ thuế quy
định tại khoản 4 Điều này.$md$,$md$GTGT_48-2024_ChươngI$md$,4,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu5$md$,$md$GTGT_48-2024$md$,$md$Điều 5. Đối tượng không chịu thuế$md$,$md$Đối tượng không chịu thuế
1. Sản phẩm cây trồng, rừng trồng, chăn nuôi, thủy sản nuôi trồng, đánh bắt
chưa chế biến thành các sản phẩm khác hoặc chỉ qua sơ chế thông thường của tổ
chức, cá nhân tự sản xuất, đánh bắt bán ra và ở khâu nhập khẩu.
2. Sản phẩm giống vật nuôi theo quy định của pháp luật về chăn nuôi, vật liệu
nhân giống cây trồng theo quy định của pháp luật về trồng trọt.
3. Thức ăn chăn nuôi theo quy định của pháp luật về chăn nuôi; thức ăn thủy
sản theo quy định của pháp luật về thủy sản.
4. Sản phẩm muối được sản xuất từ nước biển, muối mỏ tự nhiên, muối tinh,
muối i-ốt mà thành phần chính là Na-tri-clo-rua (NaCl).
5. Nhà ở thuộc tài sản công do Nhà nước bán cho người đang thuê.
6. Tưới, tiêu nước; cày, bừa đất; nạo vét kênh, mương nội đồng phục vụ sản
xuất nông nghiệp; dịch vụ thu hoạch sản phẩm nông nghiệp.
7. Chuyển quyền sử dụng đất.
8. Bảo hiểm nhân thọ, bảo hiểm sức khỏe, bảo hiểm người học, các dịch vụ
bảo hiểm khác liên quan đến con người; bảo hiểm vật nuôi, bảo hiểm cây trồng,
các dịch vụ bảo hiểm nông nghiệp khác; bảo hiểm tàu, thuyền, trang thiết bị và
các dụng cụ cần thiết khác phục vụ trực tiếp đánh bắt thủy sản; tái bảo hiểm;

bảo hiểm các công trình, thiết bị dầu khí, tàu chứa dầu mang quốc tịch nước
ngoài do nhà thầu dầu khí hoặc nhà thầu phụ nước ngoài thuê để hoạt động tại
vùng biển Việt Nam, vùng biển chồng lấn mà Việt Nam và các quốc gia có bờ
biển tiếp liền hay đối diện đã thỏa thuận đặt dưới chế độ khai thác chung.
9. Các dịch vụ tài chính, ngân hàng, kinh doanh chứng khoán, thương mại
sau đây:
a) Dịch vụ cấp tín dụng theo quy định của pháp luật về các tổ chức tín dụng và
các khoản phí được nêu cụ thể tại Hợp đồng vay vốn của Chính phủ Việt Nam với
Bên cho vay nước ngoài;
b) Dịch vụ cho vay của người nộp thuế không phải là tổ chức tín dụng;
c) Kinh doanh chứng khoán bao gồm môi giới chứng khoán, tự doanh chứng
khoán, bảo lãnh phát hành chứng khoán, tư vấn đầu tư chứng khoán, quản lý quỹ
đầu tư chứng khoán, quản lý danh mục đầu tư chứng khoán theo quy định của pháp
luật về chứng khoán;
d) Chuyển nhượng vốn bao gồm chuyển nhượng một phần hoặc toàn bộ số vốn
đã đầu tư vào tổ chức kinh tế khác (không phân biệt có thành lập hay không thành
lập pháp nhân mới), chuyển nhượng chứng khoán, chuyển nhượng quyền góp vốn
và các hình thức chuyển nhượng vốn khác theo quy định của pháp luật, kể cả
trường hợp bán doanh nghiệp cho doanh nghiệp khác để sản xuất, kinh doanh và
doanh nghiệp mua kế thừa toàn bộ quyền và nghĩa vụ của doanh nghiệp bán theo
quy định của pháp luật. Chuyển nhượng vốn quy định tại điểm này không bao gồm
chuyển nhượng dự án đầu tư, bán tài sản;
đ) Bán nợ bao gồm bán khoản phải trả và khoản phải thu;
e) Kinh doanh ngoại tệ;
g) Sản phẩm phái sinh theo quy định của pháp luật về các tổ chức tín dụng,
pháp luật về chứng khoán và pháp luật về thương mại, bao gồm: hoán đổi lãi suất;
hợp đồng kỳ hạn; hợp đồng tương lai; hợp đồng quyền chọn mua, chọn bán và sản
phẩm phái sinh khác;
h) Bán tài sản bảo đảm của khoản nợ của tổ chức mà Nhà nước sở hữu 100%
vốn điều lệ do Chính phủ thành lập có chức năng mua, bán nợ để xử lý nợ xấu của
các tổ chức tín dụng Việt Nam.
10. Các dịch vụ y tế, dịch vụ thú y sau đây:
a) Dịch vụ y tế bao gồm: dịch vụ khám bệnh, chữa bệnh, phòng bệnh cho
người, dịch vụ sinh đẻ có kế hoạch, dịch vụ điều dưỡng sức khỏe, phục hồi chức
năng cho người bệnh; dịch vụ chăm sóc người cao tuổi, người khuyết tật; vận
chuyển người bệnh, dịch vụ cho thuê phòng bệnh, giường bệnh của các cơ sở y tế;
xét nghiệm, chiếu, chụp; máu và chế phẩm máu dùng cho người bệnh.

Dịch vụ chăm sóc người cao tuổi, người khuyết tật bao gồm cả chăm sóc về y
tế, dinh dưỡng và tổ chức các hoạt động văn hóa, thể thao, giải trí, vật lý trị liệu,
phục hồi chức năng cho người cao tuổi, người khuyết tật.
Trường hợp trong gói dịch vụ chữa bệnh theo quy định của Bộ Y tế bao gồm
cả sử dụng thuốc chữa bệnh thì khoản thu từ tiền thuốc chữa bệnh nằm trong gói
dịch vụ chữa bệnh cũng thuộc đối tượng không chịu thuế giá trị gia tăng;
b) Dịch vụ thú y bao gồm: dịch vụ khám bệnh, chữa bệnh, phòng bệnh cho
vật nuôi.
11. Dịch vụ tang lễ.
12. Hoạt động duy tu, sửa chữa, xây dựng bằng nguồn vốn đóng góp của
nhân dân, vốn viện trợ nhân đạo (chiếm từ 50% tổng số vốn sử dụng cho công
trình trở lên) đối với các di tích lịch sử - văn hóa, danh lam thắng cảnh, các
công trình văn hóa, nghệ thuật, công trình phục vụ công cộng, cơ sở hạ tầng và
nhà ở cho đối tượng chính sách xã hội.
13. Hoạt động dạy học, dạy nghề theo quy định của pháp luật về giáo dục, giáo
dục nghề nghiệp.
14. Phát sóng truyền thanh, truyền hình bằng nguồn vốn ngân sách nhà nước.
15. Xuất bản, nhập khẩu, phát hành báo, tạp chí, bản tin, đặc san, sách chính
trị, sách giáo khoa, giáo trình, sách văn bản pháp luật, sách khoa học - kỹ thuật,
sách phục vụ thông tin đối ngoại, sách in bằng chữ dân tộc thiểu số và tranh, ảnh,
áp phích tuyên truyền cổ động, kể cả dưới dạng băng hoặc đĩa ghi tiếng, ghi hình,
dữ liệu điện tử; tiền, in tiền.
16. Vận chuyển hành khách công cộng bằng xe buýt, tàu điện, phương tiện
thủy nội địa.
17. Máy móc, thiết bị, phụ tùng, vật tư thuộc loại trong nước chưa sản xuất
được cần nhập khẩu để sử dụng trực tiếp cho hoạt động nghiên cứu khoa học, phát
triển công nghệ; máy móc, thiết bị, phụ tùng thay thế, phương tiện vận tải chuyên
dùng và vật tư thuộc loại trong nước chưa sản xuất được cần nhập khẩu để tiến
hành hoạt động tìm kiếm thăm dò, phát triển mỏ dầu khí; máy bay, trực thăng, tàu
lượn, giàn khoan, tàu thuyền thuộc loại trong nước chưa sản xuất được cần nhập
khẩu để tạo tài sản cố định của doanh nghiệp hoặc thuê của nước ngoài để sử dụng
cho sản xuất, kinh doanh, cho thuê.
18. Sản phẩm quốc phòng, an ninh theo danh mục do Bộ trưởng Bộ Quốc phòng,
Bộ trưởng Bộ Công an ban hành; sản phẩm, dịch vụ nhập khẩu phục vụ công nghiệp
quốc phòng, an ninh theo danh mục do Thủ tướng Chính phủ ban hành.

19. Hàng hóa nhập khẩu trong trường hợp viện trợ nhân đạo, viện trợ không
hoàn lại. Hàng hóa, dịch vụ bán cho tổ chức, cá nhân nước ngoài, tổ chức quốc tế
để viện trợ nhân đạo, viện trợ không hoàn lại cho Việt Nam.
20. Hàng hóa chuyển khẩu, quá cảnh qua lãnh thổ Việt Nam; hàng tạm nhập
khẩu, tái xuất khẩu; hàng tạm xuất khẩu, tái nhập khẩu; nguyên liệu nhập khẩu để
sản xuất, gia công hàng hóa xuất khẩu theo hợp đồng sản xuất, gia công xuất khẩu
ký kết với bên nước ngoài; hàng hóa, dịch vụ được mua bán giữa nước ngoài với
các khu phi thuế quan và giữa các khu phi thuế quan với nhau.
Hàng hóa nhập khẩu từ nước ngoài của công ty cho thuê tài chính được vận
chuyển thẳng vào khu phi thuế quan để cho doanh nghiệp trong khu phi thuế quan
thuê tài chính.
21. Chuyển giao công nghệ theo quy định của Luật Chuyển giao công nghệ;
chuyển nhượng quyền sở hữu trí tuệ theo quy định của Luật Sở hữu trí tuệ; sản
phẩm phần mềm và dịch vụ phần mềm theo quy định của pháp luật.
22. Vàng dạng thỏi, miếng chưa được chế tác thành sản phẩm mỹ nghệ, đồ
trang sức hay sản phẩm khác ở khâu nhập khẩu.
23. Sản phẩm xuất khẩu là tài nguyên, khoáng sản khai thác chưa chế biến
thành sản phẩm khác và sản phẩm xuất khẩu là tài nguyên, khoáng sản khai thác đã
chế biến thành sản phẩm khác theo Danh mục do Chính phủ quy định phù hợp với
định hướng của nhà nước về không khuyến khích xuất khẩu, hạn chế xuất khẩu các
tài nguyên, khoáng sản thô.
24. Sản phẩm nhân tạo dùng để thay thế cho bộ phận cơ thể của người bệnh,
bao gồm cả sản phẩm là bộ phận cấy ghép lâu dài trong cơ thể người; nạng, xe lăn
và dụng cụ chuyên dùng khác cho người khuyết tật.
25. Hàng hóa, dịch vụ của hộ, cá nhân sản xuất, kinh doanh có mức doanh thu
hằng năm từ 200 triệu đồng trở xuống; tài sản của tổ chức, cá nhân không kinh
doanh, không phải là người nộp thuế giá trị gia tăng bán ra; hàng dự trữ quốc gia
do cơ quan dự trữ quốc gia bán ra; các khoản thu phí, lệ phí theo quy định của
pháp luật về phí và lệ phí.
26. Hàng hóa nhập khẩu trong trường hợp sau đây:
a) Quà tặng cho cơ quan nhà nước, tổ chức chính trị, tổ chức chính trị - xã hội,
tổ chức chính trị xã hội - nghề nghiệp, tổ chức xã hội, tổ chức xã hội - nghề
nghiệp, đơn vị vũ trang nhân dân trong định mức miễn thuế nhập khẩu theo quy
định của pháp luật về thuế xuất khẩu, thuế nhập khẩu;
b) Quà biếu, quà tặng trong định mức miễn thuế nhập khẩu theo quy định của
pháp luật về thuế xuất khẩu, thuế nhập khẩu của tổ chức, cá nhân nước ngoài cho

cá nhân Việt Nam; đồ dùng của tổ chức, cá nhân nước ngoài theo tiêu chuẩn miễn
trừ ngoại giao và tài sản di chuyển trong định mức miễn thuế nhập khẩu theo quy
định của pháp luật về thuế xuất khẩu, thuế nhập khẩu;
c) Hàng hóa trong tiêu chuẩn hành lý miễn thuế nhập khẩu theo quy định của
pháp luật về thuế xuất khẩu, thuế nhập khẩu;
d) Hàng hóa nhập khẩu ủng hộ, tài trợ cho phòng, chống, khắc phục hậu quả
thảm họa, thiên tai, dịch bệnh, chiến tranh theo quy định của Chính phủ;
đ) Hàng hóa mua bán, trao đổi qua biên giới để phục vụ cho sản xuất, tiêu
dùng của cư dân biên giới thuộc Danh mục hàng hóa mua bán, trao đổi của cư dân
biên giới theo quy định của pháp luật và trong định mức miễn thuế nhập khẩu theo
quy định của pháp luật về thuế xuất khẩu, thuế nhập khẩu;
e) Di vật, cổ vật, bảo vật quốc gia theo quy định của pháp luật về di sản văn
hóa do cơ quan nhà nước có thẩm quyền nhập khẩu.
27. Cơ sở kinh doanh hàng hóa, dịch vụ không chịu thuế giá trị gia tăng quy
định tại Điều này không được khấu trừ, không được hoàn thuế giá trị gia tăng đầu
vào, trừ trường hợp được áp dụng mức thuế suất 0% quy định tại khoản 1 Điều 9
của Luật này.
28. Chính phủ quy định chi tiết Điều này. Bộ trưởng Bộ Tài chính quy định
hồ sơ, thủ tục xác định đối tượng không chịu thuế giá trị gia tăng quy định tại
Điều này.
CĂN CỨ VÀ PHƯƠNG PHÁP TÍNH THUẾ$md$,$md$GTGT_48-2024_ChươngI$md$,5,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu6$md$,$md$GTGT_48-2024$md$,$md$Điều 6. Căn cứ tính thuế$md$,$md$Căn cứ tính thuế
Căn cứ tính thuế giá trị gia tăng là giá tính thuế và thuế suất.$md$,$md$GTGT_48-2024_ChươngII$md$,6,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu7$md$,$md$GTGT_48-2024$md$,$md$Điều 7. Giá tính thuế$md$,$md$Giá tính thuế
1. Giá tính thuế được quy định như sau:
a) Đối với hàng hóa, dịch vụ do cơ sở kinh doanh bán ra là giá bán chưa có
thuế giá trị gia tăng; đối với hàng hóa, dịch vụ chịu thuế tiêu thụ đặc biệt là giá bán
đã có thuế tiêu thụ đặc biệt nhưng chưa có thuế giá trị gia tăng; đối với hàng hóa
chịu thuế bảo vệ môi trường là giá bán đã có thuế bảo vệ môi trường nhưng chưa
có thuế giá trị gia tăng; đối với hàng hóa chịu thuế tiêu thụ đặc biệt và thuế bảo vệ
môi trường là giá bán đã có thuế tiêu thụ đặc biệt và thuế bảo vệ môi trường nhưng
chưa có thuế giá trị gia tăng;

b) Đối với hàng hóa nhập khẩu là trị giá tính thuế nhập khẩu theo quy định của
pháp luật về thuế xuất khẩu, thuế nhập khẩu cộng với thuế nhập khẩu cộng với các
khoản thuế là thuế nhập khẩu bổ sung theo quy định của pháp luật (nếu có), cộng
với thuế tiêu thụ đặc biệt (nếu có) và cộng với thuế bảo vệ môi trường (nếu có);
c) Đối với hàng hóa, dịch vụ dùng để trao đổi, tiêu dùng nội bộ, biếu, tặng, cho
là giá tính thuế giá trị gia tăng của hàng hóa, dịch vụ cùng loại hoặc tương đương
tại thời điểm phát sinh các hoạt động này.
Đối với hàng hóa, dịch vụ dùng để khuyến mại theo quy định của pháp luật về
thương mại, giá tính thuế được xác định bằng không (0);
d) Đối với hoạt động cho thuê tài sản là số tiền cho thuê chưa có thuế giá trị gia tăng.
Trường hợp cho thuê theo hình thức trả tiền thuê từng kỳ hoặc trả trước tiền
thuê cho thời hạn thuê thì giá tính thuế là số tiền cho thuê trả từng kỳ hoặc trả
trước cho thời hạn thuê chưa có thuế giá trị gia tăng;
đ) Đối với hàng hóa bán theo phương thức trả góp, trả chậm là giá tính theo giá
bán trả một lần chưa có thuế giá trị gia tăng của hàng hóa đó, không bao gồm
khoản lãi trả góp, lãi trả chậm;
e) Đối với gia công hàng hóa là giá gia công chưa có thuế giá trị gia tăng;
g) Đối với hoạt động xây dựng, lắp đặt là giá trị công trình, hạng mục công trình
hay phần công việc thực hiện bàn giao chưa có thuế giá trị gia tăng. Trường hợp xây
dựng, lắp đặt không bao thầu nguyên vật liệu, máy móc, thiết bị thì giá tính thuế là giá
trị xây dựng, lắp đặt không bao gồm giá trị nguyên vật liệu và máy móc, thiết bị;
h) Đối với hoạt động kinh doanh bất động sản là giá bán bất động sản chưa có
thuế giá trị gia tăng trừ tiền sử dụng đất hoặc tiền thuê đất nộp ngân sách nhà nước
(giá đất được trừ). Chính phủ quy định việc xác định giá đất được trừ quy định tại
điểm này phù hợp với quy định của pháp luật về đất đai;
i) Đối với hoạt động đại lý, môi giới mua bán hàng hóa và dịch vụ hưởng hoa
hồng là tiền hoa hồng thu được từ các hoạt động này chưa có thuế giá trị gia tăng;
k) Đối với hàng hóa, dịch vụ được sử dụng hóa đơn thanh toán ghi giá thanh toán
là giá đã có thuế giá trị gia tăng thì giá tính thuế được xác định theo công thức sau:
Giá chưa có thuế giá trị gia tăng

=

Giá thanh toán
1 + thuế suất của hàng hóa, dịch vụ (%)

l) Đối với dịch vụ kinh doanh ca-si-nô, trò chơi điện tử có thưởng, đặt cược là
số tiền thu được từ hoạt động này trừ số tiền đã đổi trả cho khách không sử dụng
hết và số tiền trả thưởng cho khách (nếu có), đã có thuế tiêu thụ đặc biệt, chưa có
thuế giá trị gia tăng;

m) Đối với các hoạt động sản xuất, kinh doanh gồm: hoạt động sản xuất điện
của Tập đoàn Điện lực Việt Nam; vận tải, bốc xếp; dịch vụ du lịch theo hình thức
lữ hành; dịch vụ cầm đồ; sách chịu thuế giá trị gia tăng bán theo đúng giá phát
hành (giá bìa); hoạt động in; dịch vụ đại lý giám định, đại lý xét bồi thường, đại lý
đòi người thứ ba bồi hoàn, đại lý xử lý hàng bồi thường 100% hưởng tiền công
hoặc tiền hoa hồng thì giá tính thuế là giá bán chưa có thuế giá trị gia tăng. Chính
phủ quy định giá tính thuế đối với các hoạt động sản xuất, kinh doanh quy định tại
điểm này.
2. Giá tính thuế đối với hàng hóa, dịch vụ quy định tại khoản 1 Điều này bao
gồm cả khoản phụ thu và phí thu thêm mà cơ sở kinh doanh được hưởng.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$GTGT_48-2024_ChươngII$md$,7,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu8$md$,$md$GTGT_48-2024$md$,$md$Điều 8. Thời điểm xác định thuế giá trị gia tăng$md$,$md$Thời điểm xác định thuế giá trị gia tăng
1. Thời điểm xác định thuế giá trị gia tăng được quy định như sau:
a) Đối với hàng hóa là thời điểm chuyển giao quyền sở hữu hoặc quyền sử
dụng hàng hóa cho người mua hoặc thời điểm lập hóa đơn, không phân biệt đã thu
được tiền hay chưa thu được tiền;
b) Đối với dịch vụ là thời điểm hoàn thành việc cung cấp dịch vụ hoặc thời
điểm lập hóa đơn cung cấp dịch vụ, không phân biệt đã thu được tiền hay chưa thu
được tiền.
2. Thời điểm xác định thuế giá trị gia tăng đối với hàng hóa, dịch vụ sau đây
do Chính phủ quy định:
a) Hàng hóa xuất khẩu, hàng hóa nhập khẩu;
b) Dịch vụ viễn thông;
c) Dịch vụ kinh doanh bảo hiểm;
d) Hoạt động cung cấp điện, hoạt động sản xuất điện, nước sạch;
đ) Hoạt động kinh doanh bất động sản;
e) Hoạt động xây dựng, lắp đặt và hoạt động dầu khí.$md$,$md$GTGT_48-2024_ChươngII$md$,8,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu9$md$,$md$GTGT_48-2024$md$,$md$Điều 9. Thuế suất$md$,$md$Thuế suất
1. Mức thuế suất 0% áp dụng đối với hàng hóa, dịch vụ sau đây:
a) Hàng hóa xuất khẩu bao gồm: hàng hóa từ Việt Nam bán cho tổ chức, cá
nhân ở nước ngoài và được tiêu dùng ở ngoài Việt Nam; hàng hóa từ nội địa
Việt Nam bán cho tổ chức trong khu phi thuế quan và được tiêu dùng trong khu
phi thuế quan phục vụ trực tiếp cho hoạt động sản xuất xuất khẩu; hàng hóa đã
bán tại khu vực cách ly cho cá nhân (người nước ngoài hoặc người Việt Nam)
đã làm thủ tục xuất cảnh; hàng hóa đã bán tại cửa hàng miễn thuế;

b) Dịch vụ xuất khẩu bao gồm: dịch vụ cung cấp trực tiếp cho tổ chức, cá nhân
ở nước ngoài và được tiêu dùng ở ngoài Việt Nam; dịch vụ cung cấp trực tiếp cho
tổ chức ở trong khu phi thuế quan và được tiêu dùng trong khu phi thuế quan phục
vụ trực tiếp cho hoạt động sản xuất xuất khẩu;
c) Hàng hóa, dịch vụ xuất khẩu khác bao gồm: vận tải quốc tế; dịch vụ cho
thuê phương tiện vận tải được sử dụng ngoài phạm vi lãnh thổ Việt Nam; dịch vụ
của ngành hàng không, hàng hải cung cấp trực tiếp hoặc thông qua đại lý cho vận
tải quốc tế; hoạt động xây dựng, lắp đặt công trình ở nước ngoài hoặc ở trong khu
phi thuế quan; sản phẩm nội dung thông tin số cung cấp cho bên nước ngoài và có
hồ sơ, tài liệu chứng minh tiêu dùng ở ngoài Việt Nam theo quy định của Chính
phủ; phụ tùng, vật tư thay thế để sửa chữa, bảo dưỡng phương tiện, máy móc, thiết
bị cho bên nước ngoài và tiêu dùng ở ngoài Việt Nam; hàng hóa gia công chuyển
tiếp để xuất khẩu theo quy định của pháp luật; hàng hóa, dịch vụ thuộc đối tượng
không chịu thuế giá trị gia tăng khi xuất khẩu, trừ các trường hợp không áp dụng
mức thuế suất 0% quy định tại điểm d khoản này;
d) Các trường hợp không áp dụng thuế suất 0% bao gồm: chuyển giao công
nghệ, chuyển nhượng quyền sở hữu trí tuệ ra nước ngoài; dịch vụ tái bảo hiểm ra
nước ngoài; dịch vụ cấp tín dụng; chuyển nhượng vốn; sản phẩm phái sinh; dịch
vụ bưu chính, viễn thông; sản phẩm xuất khẩu quy định tại khoản 23 Điều 5 của
Luật này; thuốc lá, rượu, bia nhập khẩu sau đó xuất khẩu; xăng, dầu mua tại nội
địa bán cho cơ sở kinh doanh trong khu phi thuế quan; xe ô tô bán cho tổ chức, cá
nhân trong khu phi thuế quan.
2. Mức thuế suất 5% áp dụng đối với hàng hóa, dịch vụ sau đây:
a) Nước sạch phục vụ sản xuất và sinh hoạt không bao gồm các loại nước uống
đóng chai, đóng bình và các loại nước giải khát khác;
b) Phân bón, quặng để sản xuất phân bón, thuốc bảo vệ thực vật và chất kích
thích tăng trưởng vật nuôi theo quy định của pháp luật;
c) Dịch vụ đào đắp, nạo vét kênh, mương, ao hồ phục vụ sản xuất nông nghiệp;
nuôi trồng, chăm sóc, phòng trừ sâu bệnh cho cây trồng; sơ chế, bảo quản sản
phẩm nông nghiệp;
d) Sản phẩm cây trồng, rừng trồng (trừ gỗ, măng), chăn nuôi, thủy sản nuôi trồng,
đánh bắt chưa chế biến thành các sản phẩm khác hoặc chỉ qua sơ chế thông
thường, trừ sản phẩm quy định tại khoản 1 Điều 5 của Luật này;
đ) Mủ cao su dạng mủ cờ rếp, mủ tờ, mủ bún, mủ cốm; lưới, dây giềng và sợi
để đan lưới đánh cá;

e) Sản phẩm bằng đay, cói, tre, nứa, lá, rơm, vỏ dừa, sọ dừa, bèo tây và các sản
phẩm thủ công khác sản xuất bằng nguyên liệu tận dụng từ nông nghiệp; xơ bông
đã qua chải thô, chải kỹ; giấy in báo;
g) Tàu khai thác thủy sản tại vùng biển; máy móc, thiết bị chuyên dùng phục
vụ cho sản xuất nông nghiệp theo quy định của Chính phủ;
h) Thiết bị y tế theo quy định của pháp luật về quản lý thiết bị y tế; thuốc
phòng bệnh, chữa bệnh; dược chất, dược liệu là nguyên liệu sản xuất thuốc chữa
bệnh, thuốc phòng bệnh;
i) Thiết bị dùng để giảng dạy và học tập bao gồm: các loại mô hình, hình vẽ,
bảng, phấn, thước, com-pa;
k) Hoạt động nghệ thuật biểu diễn truyền thống, dân gian;
l) Đồ chơi cho trẻ em; sách các loại, trừ sách quy định tại khoản 15 Điều 5 của
Luật này;
m) Dịch vụ khoa học, công nghệ theo quy định của Luật Khoa học và
công nghệ;
n) Bán, cho thuê, cho thuê mua nhà ở xã hội theo quy định của Luật Nhà ở.
3. Mức thuế suất 10% áp dụng đối với hàng hóa, dịch vụ không quy định tại
khoản 1 và khoản 2 Điều này, bao gồm cả dịch vụ được các nhà cung cấp nước
ngoài không có cơ sở thường trú tại Việt Nam cung cấp cho tổ chức, cá nhân tại
Việt Nam qua kênh thương mại điện tử và các nền tảng số.
4. Cơ sở kinh doanh nhiều loại hàng hóa, dịch vụ có mức thuế suất thuế giá trị
gia tăng khác nhau (bao gồm cả đối tượng không chịu thuế giá trị gia tăng) phải
khai thuế giá trị gia tăng theo từng mức thuế suất quy định đối với từng loại hàng
hóa, dịch vụ; nếu cơ sở kinh doanh không xác định theo từng mức thuế suất thì
phải tính và nộp thuế theo mức thuế suất cao nhất của hàng hóa, dịch vụ mà cơ sở
sản xuất, kinh doanh.
5. Sản phẩm cây trồng, rừng trồng, chăn nuôi, thủy sản nuôi trồng, đánh bắt
chưa chế biến thành các sản phẩm khác hoặc chỉ qua sơ chế thông thường được sử
dụng làm thức ăn chăn nuôi, dược liệu thì áp dụng thuế suất giá trị gia tăng theo
mức thuế suất quy định cho sản phẩm cây trồng, rừng trồng, chăn nuôi, thủy sản.
Phế phẩm, phụ phẩm, phế liệu được thu hồi để tái chế, sử dụng lại khi bán ra áp
dụng mức thuế suất theo thuế suất của mặt hàng phế phẩm, phụ phẩm, phế liệu bán ra.
6. Chính phủ quy định chi tiết khoản 1 và khoản 2 Điều này. Bộ trưởng Bộ Tài
chính quy định hồ sơ, thủ tục áp dụng thuế suất thuế giá trị gia tăng 0% tại khoản 1
Điều này.$md$,$md$GTGT_48-2024_ChươngII$md$,9,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu10$md$,$md$GTGT_48-2024$md$,$md$Điều 10. Phương pháp tính thuế$md$,$md$Phương pháp tính thuế
Phương pháp tính thuế giá trị gia tăng gồm phương pháp khấu trừ thuế và
phương pháp tính trực tiếp.$md$,$md$GTGT_48-2024_ChươngII$md$,10,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu11$md$,$md$GTGT_48-2024$md$,$md$Điều 11. Phương pháp khấu trừ thuế$md$,$md$Phương pháp khấu trừ thuế
1. Phương pháp khấu trừ thuế được quy định như sau:
a) Số thuế giá trị gia tăng phải nộp theo phương pháp khấu trừ thuế bằng số
thuế giá trị gia tăng đầu ra trừ số thuế giá trị gia tăng đầu vào được khấu trừ;
b) Số thuế giá trị gia tăng đầu ra bằng tổng số thuế giá trị gia tăng của hàng
hóa, dịch vụ bán ra ghi trên hóa đơn giá trị gia tăng.
Thuế giá trị gia tăng của hàng hóa, dịch vụ bán ra ghi trên hóa đơn giá trị gia
tăng bằng giá tính thuế của hàng hóa, dịch vụ chịu thuế bán ra nhân với thuế suất
thuế giá trị gia tăng của hàng hóa, dịch vụ đó.
Trường hợp sử dụng hóa đơn ghi giá thanh toán là giá đã có thuế giá trị gia tăng
thì thuế giá trị gia tăng đầu ra được xác định bằng giá thanh toán trừ giá tính thuế giá
trị gia tăng xác định theo quy định tại điểm k khoản 1 Điều 7 của Luật này;
c) Số thuế giá trị gia tăng đầu vào được khấu trừ bằng tổng số thuế giá trị gia
tăng ghi trên hóa đơn giá trị gia tăng mua hàng hóa, dịch vụ, chứng từ nộp thuế giá
trị gia tăng của hàng hóa nhập khẩu hoặc chứng từ nộp thuế đối với trường hợp
mua dịch vụ quy định tại khoản 3, khoản 4 Điều 4 của Luật này và đáp ứng điều
kiện quy định tại Điều 14 của Luật này.
2. Phương pháp khấu trừ thuế áp dụng đối với cơ sở kinh doanh thực hiện đầy
đủ chế độ kế toán, hóa đơn, chứng từ theo quy định của pháp luật về kế toán, hóa
đơn, chứng từ bao gồm:
a) Cơ sở kinh doanh có doanh thu hằng năm từ bán hàng hóa, cung cấp dịch vụ
từ 01 tỷ đồng trở lên, trừ hộ, cá nhân sản xuất, kinh doanh;
b) Cơ sở kinh doanh tự nguyện áp dụng phương pháp khấu trừ thuế, trừ hộ, cá
nhân sản xuất, kinh doanh;
c) Tổ chức, cá nhân nước ngoài cung cấp hàng hóa, dịch vụ để tiến hành hoạt
động tìm kiếm thăm dò, phát triển mỏ dầu khí và khai thác dầu khí nộp thuế theo
phương pháp khấu trừ thuế do bên Việt Nam kê khai, khấu trừ, nộp thay.
3. Chính phủ quy định chi tiết Điều này.$md$,$md$GTGT_48-2024_ChươngII$md$,11,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu12$md$,$md$GTGT_48-2024$md$,$md$Điều 12. Phương pháp tính trực tiếp$md$,$md$Phương pháp tính trực tiếp
1. Số thuế giá trị gia tăng phải nộp theo phương pháp tính trực tiếp trên giá trị
gia tăng bằng giá trị gia tăng nhân với thuế suất thuế giá trị gia tăng áp dụng đối
với hoạt động mua, bán, chế tác vàng, bạc, đá quý.

Giá trị gia tăng của hoạt động mua, bán, chế tác vàng, bạc, đá quý được xác
định bằng giá thanh toán của vàng, bạc, đá quý bán ra trừ giá thanh toán của vàng,
bạc, đá quý mua vào tương ứng.
Trường hợp cơ sở kinh doanh có hoạt động mua, bán, chế tác vàng, bạc, đá
quý thì cơ sở kinh doanh phải hạch toán riêng hoạt động này để nộp thuế theo
phương pháp tính trực tiếp trên giá trị gia tăng.
2. Số thuế giá trị gia tăng phải nộp theo phương pháp tính trực tiếp theo doanh
thu bằng tỷ lệ % nhân với doanh thu áp dụng như sau:
a) Đối tượng áp dụng bao gồm:
a1) Doanh nghiệp, hợp tác xã, liên hiệp hợp tác xã có doanh thu hằng năm
dưới mức ngưỡng doanh thu 01 tỷ đồng, trừ trường hợp tự nguyện áp dụng phương
pháp khấu trừ thuế quy định tại khoản 2 Điều 11 của Luật này;
a2) Hộ, cá nhân sản xuất, kinh doanh, trừ trường hợp quy định tại khoản 3
Điều này;
a3) Tổ chức nước ngoài không có cơ sở thường trú tại Việt Nam, cá nhân ở
nước ngoài là đối tượng không cư trú tại Việt Nam có doanh thu phát sinh tại Việt
Nam chưa thực hiện đầy đủ chế độ kế toán, hóa đơn, chứng từ, không bao gồm các
nhà cung cấp nước ngoài quy định tại khoản 4 Điều 4 của Luật này;
a4) Tổ chức khác, trừ trường hợp nộp thuế theo phương pháp khấu trừ thuế
quy định tại khoản 2 Điều 11 của Luật này;
b) Tỷ lệ % để tính thuế giá trị gia tăng được quy định như sau:
b1) Phân phối, cung cấp hàng hóa: 1%;
b2) Dịch vụ, xây dựng không bao thầu nguyên vật liệu: 5%;
b3) Sản xuất, vận tải, dịch vụ có gắn với hàng hóa, xây dựng có bao thầu
nguyên vật liệu: 3%;
b4) Hoạt động kinh doanh khác: 2%;
c) Doanh thu để tính thuế giá trị gia tăng là tổng số tiền bán hàng hóa, dịch vụ
ghi trên hóa đơn bán hàng, bao gồm các khoản phụ thu và phí thu thêm mà cơ sở
kinh doanh được hưởng.
3. Hộ, cá nhân sản xuất, kinh doanh không thực hiện hoặc thực hiện không đầy
đủ chế độ kế toán, hóa đơn, chứng từ theo quy định của pháp luật thì nộp thuế giá
trị gia tăng theo phương pháp khoán thuế quy định tại Luật Quản lý thuế.
4. Chính phủ quy định chi tiết khoản 1 Điều này. Bộ trưởng Bộ Tài chính
quy định chi tiết nhóm hàng hóa, dịch vụ thuộc đối tượng áp dụng theo tỷ lệ %
tại điểm b khoản 2 Điều này.

KHẤU TRỪ, HOÀN THUẾ$md$,$md$GTGT_48-2024_ChươngII$md$,12,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu13$md$,$md$GTGT_48-2024$md$,$md$Điều 13. Các hành vi bị nghiêm cấm trong khấu trừ, hoàn thuế$md$,$md$Các hành vi bị nghiêm cấm trong khấu trừ, hoàn thuế
1. Mua, cho, bán, tổ chức quảng cáo, môi giới mua, bán hóa đơn.
2. Tạo lập giao dịch mua, bán hàng hóa, cung cấp dịch vụ không có thật hoặc
giao dịch không đúng quy định của pháp luật.
3. Lập hóa đơn bán hàng hóa, cung cấp dịch vụ trong thời gian tạm ngừng hoạt
động kinh doanh, trừ trường hợp lập hóa đơn giao cho khách hàng để thực hiện các
hợp đồng đã ký trước ngày thông báo tạm ngừng kinh doanh.
4. Sử dụng hóa đơn, chứng từ không hợp pháp, sử dụng không hợp pháp hóa
đơn, chứng từ theo quy định của Chính phủ.
5. Không chuyển dữ liệu hóa đơn điện tử về cơ quan thuế theo quy định.
6. Làm sai lệch, sử dụng sai mục đích, truy cập trái phép, phá hủy hệ thống
thông tin về hóa đơn, chứng từ.
7. Đưa, nhận, môi giới hối lộ hoặc thực hiện các hành vi khác liên quan đến
hóa đơn, chứng từ để được khấu trừ thuế, hoàn thuế, chiếm đoạt tiền thuế, trốn
thuế giá trị gia tăng.
8. Thông đồng, bao che; móc nối giữa công chức quản lý thuế, cơ quan quản lý
thuế và cơ sở kinh doanh, người nhập khẩu, giữa các cơ sở kinh doanh, người nhập
khẩu trong việc sử dụng hóa đơn, chứng từ không hợp pháp, sử dụng không hợp
pháp hóa đơn, chứng từ để được khấu trừ thuế, hoàn thuế, chiếm đoạt tiền thuế,
trốn thuế giá trị gia tăng.$md$,$md$GTGT_48-2024_ChươngIII$md$,13,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu14$md$,$md$GTGT_48-2024$md$,$md$Điều 14. Khấu trừ thuế giá trị gia tăng đầu vào$md$,$md$Khấu trừ thuế giá trị gia tăng đầu vào
1. Cơ sở kinh doanh nộp thuế giá trị gia tăng theo phương pháp khấu trừ thuế
được khấu trừ thuế giá trị gia tăng đầu vào như sau:
a) Thuế giá trị gia tăng đầu vào của hàng hóa, dịch vụ sử dụng cho sản xuất,
kinh doanh hàng hóa, dịch vụ chịu thuế giá trị gia tăng được khấu trừ toàn bộ, kể
cả thuế giá trị gia tăng đầu vào không được bồi thường của hàng hóa, dịch vụ chịu
thuế giá trị gia tăng bị tổn thất, hàng hóa bị hao hụt tự nhiên do tính chất lý hóa
trong quá trình vận chuyển;
b) Thuế giá trị gia tăng đầu vào của hàng hóa, dịch vụ sử dụng đồng thời cho
sản xuất, kinh doanh hàng hóa, dịch vụ chịu thuế và không chịu thuế thì chỉ được
khấu trừ số thuế giá trị gia tăng đầu vào của hàng hóa, dịch vụ sử dụng cho sản
xuất, kinh doanh hàng hóa, dịch vụ chịu thuế giá trị gia tăng. Cơ sở kinh doanh

phải hạch toán riêng thuế giá trị gia tăng đầu vào được khấu trừ và không được
khấu trừ; trường hợp không hạch toán riêng được thì số thuế giá trị gia tăng đầu
vào được khấu trừ tính theo tỷ lệ % giữa doanh thu của hàng hóa, dịch vụ chịu thuế
giá trị gia tăng so với tổng doanh thu hàng hóa, dịch vụ bán ra;
c) Thuế giá trị gia tăng đầu vào của hàng hóa, dịch vụ bán cho tổ chức, cá nhân
sử dụng vốn viện trợ nhân đạo, viện trợ không hoàn lại được khấu trừ toàn bộ;
d) Thuế giá trị gia tăng đầu vào của hàng hóa, dịch vụ sử dụng cho hoạt động
tìm kiếm thăm dò, phát triển mỏ dầu khí được khấu trừ toàn bộ;
đ) Thuế giá trị gia tăng đầu vào phát sinh trong tháng, quý nào được kê khai,
khấu trừ khi xác định số thuế phải nộp của tháng, quý đó. Số thuế giá trị gia tăng
đầu vào chưa được khấu trừ hết trong tháng, quý thì được khấu trừ vào tháng, quý
tiếp theo.
Trường hợp cơ sở kinh doanh phát hiện số thuế giá trị gia tăng đầu vào khi kê
khai, khấu trừ bị sai, sót thì được khai thuế trước khi cơ quan thuế, cơ quan có
thẩm quyền công bố quyết định kiểm tra thuế, thanh tra thuế như sau:
Người nộp thuế thực hiện khai bổ sung vào tháng, quý phát sinh số thuế giá trị
gia tăng đầu vào bị sai, sót nếu việc khai thuế vào tháng, quý phát sinh số thuế giá
trị gia tăng đầu vào bị sai, sót làm tăng số thuế phải nộp hoặc giảm số thuế được
hoàn; người nộp thuế phải nộp đủ số tiền thuế phải nộp tăng thêm hoặc bị thu hồi
số tiền thuế đã được hoàn tương ứng và nộp tiền chậm nộp vào ngân sách nhà
nước (nếu có).
Người nộp thuế thực hiện khai vào tháng, quý phát hiện sai, sót nếu việc khai
thuế vào tháng, quý phát sinh số thuế giá trị gia tăng đầu vào bị sai, sót làm giảm
số tiền thuế phải nộp hoặc chỉ làm tăng hoặc giảm số thuế giá trị gia tăng còn được
khấu trừ chuyển sang tháng, quý sau;
e) Đối với số thuế giá trị gia tăng đầu vào không được khấu trừ, cơ sở kinh
doanh được tính vào chi phí để tính thuế thu nhập doanh nghiệp hoặc tính vào
nguyên giá của tài sản cố định theo quy định của pháp luật về thuế thu nhập doanh
nghiệp, trừ số thuế giá trị gia tăng của hàng hóa, dịch vụ mua vào không có chứng
từ thanh toán không dùng tiền mặt theo quy định của Chính phủ;
g) Chính phủ quy định chi tiết việc khấu trừ thuế giá trị gia tăng đầu vào đối
với: hàng hóa, dịch vụ hình thành tài sản cố định phục vụ cho người lao động;
trường hợp góp vốn bằng tài sản; hàng hóa, dịch vụ mua vào dưới hình thức ủy
quyền cho tổ chức, cá nhân khác mà hóa đơn mang tên tổ chức, cá nhân được ủy
quyền; tài sản cố định là ô tô chở người từ 09 chỗ ngồi trở xuống; cơ sở sản xuất,
kinh doanh tổ chức sản xuất khép kín, hạch toán tập trung.

2. Điều kiện khấu trừ thuế giá trị gia tăng đầu vào được quy định như sau:
a) Có hóa đơn giá trị gia tăng mua hàng hóa, dịch vụ hoặc chứng từ nộp thuế
giá trị gia tăng ở khâu nhập khẩu hoặc chứng từ nộp thuế giá trị gia tăng thay cho
phía nước ngoài quy định tại khoản 3 và khoản 4 Điều 4 của Luật này. Bộ trưởng
Bộ Tài chính quy định chứng từ nộp thuế giá trị gia tăng thay cho phía nước ngoài;
b) Có chứng từ thanh toán không dùng tiền mặt đối với hàng hóa, dịch vụ mua
vào, trừ một số trường hợp đặc thù theo quy định của Chính phủ;
c) Đối với hàng hóa, dịch vụ xuất khẩu, ngoài các điều kiện quy định tại điểm a
và điểm b khoản này còn phải có: hợp đồng ký kết với bên nước ngoài về việc bán,
gia công hàng hóa, cung cấp dịch vụ; hóa đơn bán hàng hóa, cung cấp dịch vụ;
chứng từ thanh toán không dùng tiền mặt; tờ khai hải quan đối với hàng hóa xuất
khẩu; phiếu đóng gói, vận đơn, chứng từ bảo hiểm hàng hóa (nếu có). Chính phủ
quy định về điều kiện khấu trừ đối với trường hợp xuất khẩu hàng hóa qua sàn
thương mại điện tử ở nước ngoài và một số trường hợp đặc thù khác.
3. Cơ sở kinh doanh không đáp ứng quy định về khấu trừ thuế tại khoản 1 và
khoản 2 Điều này và các hóa đơn, chứng từ được lập từ các hành vi bị nghiêm cấm
tại Luật này thì không được khấu trừ thuế giá trị gia tăng.
4. Chính phủ quy định chi tiết Điều này.$md$,$md$GTGT_48-2024_ChươngIII$md$,14,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu15$md$,$md$GTGT_48-2024$md$,$md$Điều 15. Hoàn thuế giá trị gia tăng$md$,$md$Hoàn thuế giá trị gia tăng
1. Việc hoàn thuế đối với xuất khẩu được quy định như sau:
a) Cơ sở kinh doanh trong tháng, quý có hàng hóa, dịch vụ xuất khẩu nếu có số
thuế giá trị gia tăng đầu vào chưa được khấu trừ hết từ 300 triệu đồng trở lên thì
được hoàn thuế giá trị gia tăng theo tháng, quý, trừ trường hợp hàng hóa nhập khẩu
sau đó xuất khẩu sang nước khác;
b) Cơ sở kinh doanh trong tháng, quý vừa có hàng hóa, dịch vụ xuất khẩu, vừa
có hàng hóa, dịch vụ tiêu thụ nội địa thì cơ sở kinh doanh phải hạch toán riêng số
thuế giá trị gia tăng đầu vào sử dụng cho sản xuất, kinh doanh hàng hóa, dịch vụ
xuất khẩu; trường hợp không hạch toán riêng được thì số thuế giá trị gia tăng đầu
vào của hàng hóa, dịch vụ xuất khẩu được xác định theo tỷ lệ giữa doanh thu của
hàng hóa, dịch vụ xuất khẩu trên tổng doanh thu hàng hóa, dịch vụ chịu thuế của
kỳ hoàn thuế. Kỳ hoàn thuế được xác định từ kỳ tính thuế giá trị gia tăng có số
thuế giá trị gia tăng đầu vào chưa khấu trừ hết liên tục chưa được hoàn thuế đến kỳ
tính thuế có đề nghị hoàn thuế.
Số thuế giá trị gia tăng đầu vào của hàng hóa, dịch vụ xuất khẩu (bao gồm số
thuế giá trị gia tăng đầu vào hạch toán riêng được và số thuế giá trị gia tăng đầu
vào được xác định theo tỷ lệ nêu trên) nếu sau khi bù trừ với số thuế giá trị gia tăng
phải nộp của hàng hóa, dịch vụ tiêu thụ nội địa còn lại từ 300 triệu đồng trở lên thì

cơ sở kinh doanh được hoàn thuế cho hàng hóa, dịch vụ xuất khẩu. Số thuế giá trị
gia tăng được hoàn của hàng hóa, dịch vụ xuất khẩu không vượt quá 10% doanh
thu của hàng hóa, dịch vụ xuất khẩu của kỳ hoàn thuế. Số thuế giá trị gia tăng đầu
vào đã được xác định cho hàng hóa, dịch vụ xuất khẩu nhưng chưa được hoàn do
vượt quá 10% doanh thu của hàng hóa, dịch vụ xuất khẩu của kỳ hoàn thuế trước
được khấu trừ vào kỳ tính thuế tiếp theo để xác định số thuế giá trị gia tăng được
hoàn của hàng hóa, dịch vụ xuất khẩu kỳ hoàn thuế tiếp theo.
2. Việc hoàn thuế đối với đầu tư được quy định như sau:
a) Cơ sở kinh doanh đã đăng ký nộp thuế giá trị gia tăng theo phương pháp
khấu trừ thuế có dự án đầu tư (dự án đầu tư mới, dự án đầu tư mở rộng) theo quy
định của pháp luật về đầu tư (bao gồm cả dự án đầu tư được chia thành nhiều giai
đoạn đầu tư hoặc nhiều hạng mục đầu tư, trừ trường hợp dự án đầu tư không hình
thành tài sản cố định của doanh nghiệp) đang trong giai đoạn đầu tư hoặc dự án
tìm kiếm thăm dò, phát triển mỏ dầu khí đang trong giai đoạn đầu tư có số thuế giá
trị gia tăng đầu vào phát sinh trong giai đoạn đầu tư mà chưa được hoàn thuế thì cơ
sở kinh doanh thực hiện bù trừ với số thuế giá trị gia tăng phải nộp của hoạt động
sản xuất, kinh doanh đang thực hiện (nếu có). Sau khi bù trừ nếu số thuế giá trị gia
tăng đầu vào của dự án đầu tư chưa được khấu trừ hết từ 300 triệu đồng trở lên thì
được hoàn thuế giá trị gia tăng.
Trường hợp dự án đầu tư đã hoàn thành (bao gồm cả dự án đầu tư chia thành
nhiều giai đoạn, hạng mục đầu tư có giai đoạn, hạng mục đầu tư đã hoàn thành)
nhưng cơ sở kinh doanh chưa thực hiện hoàn thuế giá trị gia tăng phát sinh trong giai
đoạn đầu tư (hạng mục đầu tư, giai đoạn đầu tư đã hoàn thành) thì cơ sở kinh doanh
thực hiện nộp hồ sơ hoàn thuế giá trị gia tăng theo quy định trong thời hạn 01 năm kể
từ ngày dự án đầu tư hoặc ngày giai đoạn đầu tư, hạng mục đầu tư hoàn thành.
Ngày dự án đầu tư hoặc ngày giai đoạn, hạng mục đầu tư hoàn thành là ngày
phát sinh doanh thu của dự án đầu tư hoặc ngày phát sinh doanh thu của giai đoạn,
hạng mục đầu tư. Doanh thu quy định tại khoản này không bao gồm doanh thu
phát sinh trong giai đoạn chạy thử, doanh thu hoạt động tài chính, thanh lý nguyên
vật liệu của dự án đầu tư;
b) Cơ sở kinh doanh không được hoàn thuế giá trị gia tăng mà được kết chuyển
số thuế chưa được khấu trừ của dự án đầu tư theo quy định của pháp luật về đầu tư
sang kỳ tiếp theo đối với các trường hợp sau đây:
b1) Dự án đầu tư của cơ sở kinh doanh không góp đủ số vốn điều lệ như đã
đăng ký tại thời điểm nộp hồ sơ hoàn thuế; kinh doanh ngành, nghề đầu tư kinh
doanh có điều kiện khi chưa đủ các điều kiện kinh doanh theo quy định của pháp
luật về đầu tư hoặc không bảo đảm duy trì đủ điều kiện kinh doanh trong quá trình

hoạt động, trừ dự án đầu tư trong giai đoạn đầu tư, theo quy định của pháp luật về
đầu tư, pháp luật chuyên ngành chưa phải đề nghị cơ quan nhà nước có thẩm
quyền cấp giấy kinh doanh ngành, nghề đầu tư kinh doanh có điều kiện, dự án đầu
tư theo quy định của pháp luật về đầu tư, pháp luật chuyên ngành không phải có
giấy kinh doanh ngành, nghề đầu tư kinh doanh có điều kiện;
b2) Dự án đầu tư khai thác tài nguyên, khoáng sản (không bao gồm dự án tìm
kiếm thăm dò, phát triển mỏ dầu khí quy định tại điểm a khoản này) và dự án đầu
tư sản xuất sản phẩm là tài nguyên, khoáng sản khai thác đã chế biến thành sản
phẩm khác quy định tại khoản 23 Điều 5 của Luật này.
3. Cơ sở kinh doanh chỉ sản xuất hàng hóa, cung cấp dịch vụ chịu thuế suất
thuế giá trị gia tăng 5% nếu có số thuế giá trị gia tăng đầu vào chưa được khấu trừ
hết từ 300 triệu đồng trở lên sau 12 tháng liên tục hoặc 04 quý liên tục thì được
hoàn thuế giá trị gia tăng; trường hợp cơ sở kinh doanh sản xuất hàng hóa, cung
cấp dịch vụ chịu nhiều mức thuế suất thuế giá trị gia tăng thì được hoàn thuế theo
tỷ lệ phân bổ do Chính phủ quy định.
4. Cơ sở kinh doanh nộp thuế giá trị gia tăng theo phương pháp khấu trừ thuế
được hoàn thuế giá trị gia tăng khi giải thể, phá sản có số thuế giá trị gia tăng nộp
thừa hoặc số thuế giá trị gia tăng đầu vào chưa được khấu trừ hết.
Trường hợp tổ hợp tác nộp thuế theo phương pháp khấu trừ thuế chuyển đổi
thành hợp tác xã thì hợp tác xã được kế thừa số thuế giá trị gia tăng nộp thừa hoặc
số thuế giá trị gia tăng đầu vào chưa được khấu trừ hết của tổ hợp tác để khấu trừ,
hoàn thuế theo quy định.
5. Người nước ngoài, người Việt Nam định cư ở nước ngoài mang hộ chiếu
hoặc giấy tờ có giá trị đi lại quốc tế được hoàn thuế đối với hàng hóa mua tại
Việt Nam mang theo khi xuất cảnh.
Chính phủ quy định hồ sơ, thủ tục, số thuế được hoàn, phương thức hoàn thuế
đối với trường hợp quy định tại khoản này.
6. Việc hoàn thuế giá trị gia tăng đối với các chương trình, dự án sử dụng vốn
hỗ trợ phát triển chính thức (ODA) không hoàn lại hoặc viện trợ không hoàn lại,
viện trợ nhân đạo được quy định như sau:
a) Chủ chương trình, dự án hoặc nhà thầu chính, tổ chức do phía nhà tài trợ
nước ngoài chỉ định việc quản lý chương trình, dự án sử dụng vốn ODA không
hoàn lại được hoàn số thuế giá trị gia tăng đã trả cho hàng hóa, dịch vụ mua tại
Việt Nam để phục vụ cho chương trình, dự án;
b) Tổ chức ở Việt Nam sử dụng tiền viện trợ không hoàn lại, tiền viện trợ nhân
đạo của tổ chức, cá nhân nước ngoài để mua hàng hóa, dịch vụ phục vụ cho
chương trình, dự án viện trợ không hoàn lại, viện trợ nhân đạo tại Việt Nam thì
được hoàn số thuế giá trị gia tăng đã trả cho hàng hóa, dịch vụ đó.

7. Đối tượng được hưởng quyền ưu đãi miễn trừ ngoại giao theo quy định của
pháp luật về ngoại giao mua hàng hóa, dịch vụ tại Việt Nam để sử dụng được hoàn
số thuế giá trị gia tăng đã trả ghi trên hóa đơn giá trị gia tăng hoặc trên chứng từ
thanh toán ghi giá thanh toán đã có thuế giá trị gia tăng.
8. Cơ sở kinh doanh có quyết định hoàn thuế giá trị gia tăng của cơ quan có
thẩm quyền theo quy định của pháp luật và trường hợp hoàn thuế giá trị gia tăng
theo điều ước quốc tế mà nước Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên.
9. Cơ sở kinh doanh thuộc trường hợp hoàn thuế quy định tại Điều này phải
đáp ứng điều kiện sau đây:
a) Cơ sở kinh doanh thuộc trường hợp được hoàn thuế theo quy định tại các
khoản 1, 2, 3 và 4 Điều này phải là cơ sở kinh doanh nộp thuế giá trị gia tăng theo
phương pháp khấu trừ thuế, lập và lưu giữ sổ kế toán, chứng từ kế toán theo quy
định của pháp luật về kế toán; có tài khoản tiền gửi tại ngân hàng theo mã số thuế
của cơ sở kinh doanh;
b) Đáp ứng quy định về khấu trừ thuế giá trị gia tăng đầu vào theo quy định tại khoản 2
Điều 14 và không thuộc trường hợp quy định tại khoản 3 Điều 14 của Luật này;
c) Người bán đã kê khai, nộp thuế giá trị gia tăng theo quy định đối với hóa
đơn đã xuất cho cơ sở kinh doanh đề nghị hoàn thuế.
10. Người nộp thuế thuộc trường hợp hoàn thuế giá trị gia tăng, có số thuế giá
trị gia tăng đầu vào đáp ứng đầy đủ điều kiện hoàn thuế theo quy định tại Điều này
và tuân thủ các quy định về khai thuế theo quy định của pháp luật về quản lý thuế,
lập hồ sơ hoàn thuế giá trị gia tăng đối với từng trường hợp hoàn thuế giá trị gia
tăng và gửi đến cơ quan thuế có thẩm quyền tiếp nhận.
Cơ quan thuế phân loại hồ sơ hoàn thuế giá trị gia tăng thuộc diện hoàn thuế
trước hoặc kiểm tra trước hoàn thuế và giải quyết hồ sơ hoàn thuế giá trị gia tăng
theo quy định của pháp luật về quản lý thuế.
11. Chính phủ quy định chi tiết Điều này.$md$,$md$GTGT_48-2024_ChươngIII$md$,15,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu16$md$,$md$GTGT_48-2024$md$,$md$Điều 16. Hóa đơn, chứng từ$md$,$md$Hóa đơn, chứng từ
1. Việc mua bán hàng hóa, dịch vụ phải có hóa đơn, chứng từ theo quy định
của pháp luật và các quy định sau đây:
a) Cơ sở kinh doanh áp dụng phương pháp khấu trừ thuế sử dụng hóa đơn giá
trị gia tăng. Trường hợp bán hàng hóa, dịch vụ chịu thuế giá trị gia tăng mà trên
hóa đơn giá trị gia tăng không ghi khoản thuế giá trị gia tăng thì thuế giá trị gia
tăng đầu ra được xác định bằng giá thanh toán ghi trên hóa đơn nhân với thuế suất
thuế giá trị gia tăng, trừ trường hợp quy định tại khoản 2 Điều này;

b) Cơ sở kinh doanh áp dụng phương pháp tính trực tiếp sử dụng hóa đơn
bán hàng.
2. Đối với các loại tem, vé, thẻ là chứng từ thanh toán in sẵn giá thanh toán thì
giá thanh toán tem, vé, thẻ đó đã bao gồm thuế giá trị gia tăng.
ĐIỀU KHOẢN THI HÀNH$md$,$md$GTGT_48-2024_ChươngIII$md$,16,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu17$md$,$md$GTGT_48-2024$md$,$md$Điều 17. Sửa đổi, bổ sung khoản 1 Điều 3 của Luật Thuế thu nhập cá nhân$md$,$md$Sửa đổi, bổ sung khoản 1 Điều 3 của Luật Thuế thu nhập cá nhân
số 04/2007/QH12 đã được sửa đổi, bổ sung một số điều theo Luật số 26/2012/QH13
và Luật số 71/2014/QH13
“1. Thu nhập từ kinh doanh, bao gồm:
a) Thu nhập từ hoạt động sản xuất, kinh doanh hàng hóa, dịch vụ;
b) Thu nhập từ hoạt động hành nghề độc lập của cá nhân có giấy phép hoặc
chứng chỉ hành nghề theo quy định của pháp luật.
Thu nhập từ kinh doanh quy định tại khoản này không bao gồm thu nhập của
hộ, cá nhân sản xuất, kinh doanh có doanh thu dưới mức quy định tại khoản 25
Điều 5 của Luật Thuế giá trị gia tăng.”$md$,$md$GTGT_48-2024_ChươngIV$md$,17,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.units(unit_id,doc_id,name,content,parent_id,ordinal,valid_from,valid_to) values($md$GTGT_48-2024_Dieu18$md$,$md$GTGT_48-2024$md$,$md$Điều 18. Hiệu lực thi hành$md$,$md$Hiệu lực thi hành
1. Luật này có hiệu lực thi hành từ ngày 01 tháng 7 năm 2025, trừ trường hợp
quy định tại khoản 2 Điều này.
2. Quy định về mức doanh thu của hộ, cá nhân sản xuất, kinh doanh thuộc đối
tượng không chịu thuế tại khoản 25 Điều 5 của Luật này và Điều 17 của Luật này
có hiệu lực thi hành từ ngày 01 tháng 01 năm 2026.
3. Luật Thuế giá trị gia tăng số 13/2008/QH12 đã được sửa đổi, bổ sung một
số điều theo Luật số 31/2013/QH13, Luật số 71/2014/QH13 và Luật số 106/2016/QH13
hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành./.
Luật này được Quốc hội nước Cộng hòa xã hội chủ nghĩa Việt Nam khóa XV,
kỳ họp thứ 8 thông qua ngày 26 tháng 11 năm 2024.
CHỦ TỊCH QUỐC HỘI
Trần Thanh Mẫn$md$,$md$GTGT_48-2024_ChươngIV$md$,18,$md$2025-07-01$md$,null) on conflict(unit_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-001$md$,$md$Đăng ký thuế$md$,$md$Tôi là đại diện Hộ kinh doanh Hải Nam. Tôi muốn biết khi mới ra kinh doanh và thuộc diện đăng ký thuế trực tiếp với cơ quan thuế thì thời hạn nộp hồ sơ đăng ký thuế lần đầu là bao lâu?$md$,$md$Theo quy định, thời hạn nộp hồ sơ đăng ký thuế lần đầu khi đăng ký trực tiếp với cơ quan thuế là trong vòng 10 ngày làm việc kể từ ngày bạn được cấp Giấy chứng nhận đăng ký hộ kinh doanh.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-002$md$,$md$Đăng ký thuế$md$,$md$Tôi chuẩn bị thành lập một hộ kinh doanh tạp hóa tại nhà ở quận Cầu Giấy, Hà Nội. Mã số thuế cấp cho hộ kinh doanh của tôi sẽ được quy định như thế nào?$md$,$md$Mã số thuế cấp cho hộ kinh doanh của bạn sẽ chính là mã số thuế cá nhân của bạn (người đại diện hộ kinh doanh). Mã số thuế này có cấu trúc 10 chữ số và sẽ đi theo bạn trong suốt quá trình hoạt động.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-003$md$,$md$Đăng ký thuế$md$,$md$Tôi là đại diện hộ kinh doanh bánh kẹo ở Nam Định. Gần đây tôi có thay đổi thông tin người đại diện hộ kinh doanh. Tôi phải làm thủ tục thay đổi thông tin đăng ký thuế ở đâu và như thế nào?$md$,$md$Hộ kinh doanh thực hiện thay đổi thông tin đăng ký thuế cùng với việc thay đổi nội dung đăng ký hộ kinh doanh tại cơ quan đăng ký kinh doanh. Bạn không cần nộp hồ sơ thay đổi riêng tới cơ quan thuế.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-004$md$,$md$Đăng ký thuế$md$,$md$Tôi có một hộ kinh doanh quần áo thời trang có địa điểm kinh doanh cố định ở TP. Hồ Chí Minh. Tôi nên nộp hồ sơ đăng ký thuế lần đầu ở đâu?$md$,$md$Bạn nộp hồ sơ đăng ký thuế lần đầu tại Chi cục Thuế hoặc Chi cục Thuế khu vực nơi đặt địa điểm kinh doanh cố định của hộ kinh doanh.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-005$md$,$md$Đăng ký thuế$md$,$md$Tôi kinh doanh bán hàng lưu động (không có địa điểm cố định). Tôi phải thực hiện đăng ký thuế ở đâu?$md$,$md$Trường hợp bạn kinh doanh lưu động, không có địa điểm kinh doanh cố định thì bạn nộp hồ sơ đăng ký thuế tại Chi cục Thuế hoặc Chi cục Thuế khu vực nơi bạn cư trú (thường trú hoặc tạm trú).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-006$md$,$md$Đăng ký thuế$md$,$md$Hộ kinh doanh của tôi trước đây bị cơ quan thuế thông báo không hoạt động tại địa chỉ đã đăng ký. Nay tôi muốn mở một hộ kinh doanh mới đứng tên tôi thì có được không?$md$,$md$Bạn không được đăng ký hộ kinh doanh mới khi chưa hoàn thành nghĩa vụ nộp thuế của hộ kinh doanh cũ đang bị cơ quan thuế thông báo không hoạt động tại địa chỉ đã đăng ký.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-007$md$,$md$Đăng ký thuế$md$,$md$Hộ kinh doanh của tôi đăng ký liên thông một cửa. Khi chấm dứt hoạt động, hồ sơ chấm dứt hiệu lực mã số thuế của tôi được cơ quan thuế xử lý thế nào?$md$,$md$Khi bạn làm thủ tục chấm dứt hoạt động hộ kinh doanh tại cơ quan đăng ký kinh doanh, cơ quan đăng ký kinh doanh sẽ truyền thông tin sang cơ quan thuế qua Hệ thống thông tin quốc gia để chấm dứt hiệu lực mã số thuế mà bạn không cần nộp hồ sơ giấy riêng biệt đến cơ quan thuế.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-008$md$,$md$Đăng ký thuế$md$,$md$Tôi muốn thành lập thêm một địa điểm kinh doanh phụ ngoài trụ sở chính của hộ kinh doanh tại Hà Nội. Có phải đăng ký mã số thuế 13 số riêng cho địa điểm kinh doanh mới này không?$md$,$md$Không cần cấp mã số thuế 13 số riêng cho địa điểm kinh doanh mới nữa. Thủ tục chấm dứt hoặc quản lý nghĩa vụ thuế của địa điểm kinh doanh sẽ được phối hợp thực hiện trực tiếp thông qua mã số thuế 10 số của trụ sở chính hộ kinh doanh.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-009$md$,$md$Đăng ký thuế$md$,$md$Nếu hộ kinh doanh của tôi bị cơ quan thuế ban hành thông báo tạm ngừng hoạt động do không tìm thấy tại địa chỉ đã đăng ký thì mã số thuế của tôi có bị chấm dứt vĩnh viễn không?$md$,$md$Cơ quan thuế sẽ tạm thời chuyển trạng thái mã số thuế của bạn sang diện không hoạt động tại địa chỉ đã đăng ký chứ không chấm dứt mã số thuế ngay. Tuy nhiên, bạn sẽ phải thực hiện xác minh và hoàn thành các nghĩa vụ thuế trước khi mở hoạt động trở lại.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-010$md$,$md$Đăng ký thuế$md$,$md$Hộ kinh doanh của tôi đã làm thủ tục khôi phục hoạt động kinh doanh tại cơ quan đăng ký kinh doanh. Cơ quan thuế sẽ xử lý khôi phục mã số thuế cho tôi trong thời hạn bao lâu?$md$,$md$Ngay trong ngày nhận được thông tin khôi phục tình trạng pháp lý do cơ quan đăng ký kinh doanh truyền sang, cơ quan thuế có trách nhiệm khôi phục mã số thuế cho hộ kinh doanh của bạn.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-011$md$,$md$Khai thuế$md$,$md$Năm 2026, doanh thu thực tế từ bán hàng ăn của tôi dự kiến là 800 triệu đồng/năm. Tôi có phải nộp thuế GTGT và thuế TNCN không?$md$,$md$Không. Theo quy định mới nhất được sửa đổi bởi Nghị định số 141/2026/NĐ-CP, ngưỡng doanh thu không chịu thuế GTGT và không phải nộp thuế TNCN đối với hộ kinh doanh, cá nhân kinh doanh đã được nâng lên mức từ 01 tỷ đồng trở xuống.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-012$md$,$md$Khai thuế$md$,$md$Hộ kinh doanh của tôi hoạt động trong lĩnh vực may mặc, có doanh thu năm 2026 là 1,5 tỷ đồng. Tôi áp dụng phương pháp kê khai. Tôi phải khai thuế giá trị gia tăng theo tháng hay theo quý?$md$,$md$Bạn thực hiện khai và nộp thuế GTGT theo quý, do doanh thu năm của bạn từ 50 tỷ đồng trở xuống.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-013$md$,$md$Khai thuế$md$,$md$Tôi có hộ kinh doanh chuỗi phân phối điện máy quy mô lớn với doanh thu năm 2026 đạt 60 tỷ đồng. Tôi phải kê khai thuế GTGT theo tháng hay quý và hạn nộp hồ sơ là khi nào?$md$,$md$Do doanh thu năm của bạn vượt trên 50 tỷ đồng, bạn phải thực hiện khai thuế GTGT theo tháng. Thời hạn nộp hồ sơ khai thuế tháng chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-014$md$,$md$Khai thuế$md$,$md$Hộ kinh doanh của tôi nộp thuế theo quý, vậy thời hạn nộp hồ sơ khai thuế và nộp thuế quý I năm 2026 chậm nhất là ngày nào?$md$,$md$Thời hạn nộp hồ sơ khai thuế và nộp thuế theo quý chậm nhất là ngày cuối cùng của tháng đầu tiên của quý tiếp theo. Đối với quý I năm 2026, thời hạn nộp chậm nhất là ngày 30 tháng 4 năm 2026 (hoặc ngày cuối tháng 4 tùy số ngày của tháng).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-015$md$,$md$Khai thuế$md$,$md$Hộ kinh doanh của tôi bán hàng trên Shopee (Sàn giao dịch TMĐT). Sàn Shopee có chức năng đặt hàng trực tuyến và thanh toán trực tiếp. Sàn có trách nhiệm gì đối với số thuế của tôi phát sinh trên sàn?$md$,$md$Chủ quản sàn giao dịch thương mại điện tử Shopee (nếu có chức năng đặt hàng trực tuyến và thanh toán trực tiếp) có nghĩa vụ khấu trừ thuế, nộp thuế thay và kê khai số thuế đã khấu trừ thay cho bạn.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-016$md$,$md$Khai thuế$md$,$md$Tôi có kinh doanh thêm một cửa hàng bán hoa tại quận Đống Đa, ngoài trụ sở chính tại quận Hoàn Kiếm, Hà Nội. Tôi kê khai thuế cho địa điểm kinh doanh phụ này như thế nào?$md$,$md$Bạn thực hiện kê khai thuế tổng hợp chung cho cả trụ sở chính và địa điểm kinh doanh phụ trên cùng 1 hồ sơ khai thuế, rồi nộp cho cơ quan thuế quản lý trực tiếp trụ sở chính ở quận Hoàn Kiếm. Tuy nhiên, tiền thuế phát sinh tại địa điểm kinh doanh phụ nào thì nộp cho địa bàn quận nơi có địa điểm kinh doanh đó.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-017$md$,$md$Khai thuế$md$,$md$Hộ kinh doanh của tôi chỉ bán hàng qua Facebook (không có cửa hàng vật lý và không dùng sàn TMĐT có thanh toán trực tuyến). Tôi phải nộp hồ sơ khai thuế ở đâu?$md$,$md$Nếu bạn kinh doanh trực tuyến không qua sàn có chức năng thanh toán và không có địa điểm cố định, bạn nộp hồ sơ khai thuế tại cơ quan thuế quản lý địa bàn nơi bạn cư trú (nơi ở hiện tại, tạm trú hoặc thường trú).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-018$md$,$md$Khai thuế$md$,$md$Tôi cho một doanh nghiệp thuê nhà làm văn phòng với tiền thuê là 120 triệu đồng/năm. Trong hợp đồng ghi rõ bên đi thuê có nghĩa vụ nộp thuế thay cho chủ nhà. Doanh nghiệp đi thuê có phải kê khai thuế thay cho tôi không?$md$,$md$Có. Doanh nghiệp đi thuê có trách nhiệm khấu trừ, kê khai và nộp thuế giá trị gia tăng, thuế thu nhập cá nhân thay cho bạn khi chi trả tiền thuê nhà cho bạn.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-019$md$,$md$Khai thuế$md$,$md$Tôi có kinh doanh bán quần áo trẻ em và có doanh thu năm 2026 là 1,2 tỷ đồng. Tôi lựa chọn khai thuế TNCN theo phương pháp tỷ lệ trên doanh thu. Tôi có được chọn địa điểm kinh doanh để áp dụng mức trừ 1 tỷ đồng không chịu thuế trước khi tính thuế TNCN không?$md$,$md$Có. Nếu bạn nộp thuế TNCN trên doanh thu tính thuế và có nhiều ngành nghề hoặc địa điểm kinh doanh, bạn được quyền lựa chọn ngành nghề hoặc địa điểm kinh doanh có lợi nhất để áp dụng mức trừ 01 tỷ đồng (hoặc 500 triệu đồng ban đầu được nâng lên 01 tỷ đồng) trước khi tính thuế TNCN.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-020$md$,$md$Khai thuế$md$,$md$Tôi mới thành lập hộ kinh doanh quán cà phê từ ngày 01/03/2026 và tự xác định doanh thu thực tế đến hết 30/06/2026 dưới 1 tỷ đồng. Tôi phải làm thủ tục thông báo doanh thu khi nào?$md$,$md$Do bạn mới ra kinh doanh trong 06 tháng đầu năm và có doanh thu từ mức miễn thuế trở xuống, bạn phải thực hiện thông báo doanh thu thực tế phát sinh kể từ khi bắt đầu hoạt động đến hết ngày 30 tháng 6 với cơ quan thuế quản lý trực tiếp chậm nhất là ngày 31 tháng 7 năm 2026.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-021$md$,$md$Khai thuế$md$,$md$Tôi bắt đầu kinh doanh cửa hàng ăn uống từ ngày 01/09/2026 (06 tháng cuối năm) và doanh thu dưới mức chịu thuế. Tôi phải nộp thông báo doanh thu vào thời hạn nào?$md$,$md$Bạn thực hiện thông báo doanh thu thực tế phát sinh của năm 2026 chậm nhất là ngày 31 tháng 01 của năm dương lịch tiếp theo (tức là ngày 31/01/2027).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-022$md$,$md$Khai thuế$md$,$md$Hộ kinh doanh mới thành lập của tôi có doanh thu luỹ kế cộng dồn đến tháng 8 năm 2026 đạt 1,2 tỷ đồng (vượt ngưỡng miễn thuế). Tôi phải thực hiện khai thuế từ thời điểm nào?$md$,$md$Bạn phải thực hiện khai thuế theo quý kể từ quý phát sinh doanh thu vượt ngưỡng (ở đây là quý III năm 2026 khi doanh thu luỹ kế vượt 01 tỷ đồng).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-023$md$,$md$Chế độ kế toán$md$,$md$Tôi là chủ hộ kinh doanh bánh kẹo mứt Tết. Tôi có thể áp dụng Chế độ kế toán cho doanh nghiệp siêu nhỏ theo Thông tư số 58/2026/TT-BTC cho hộ kinh doanh của mình không?$md$,$md$Có. Hộ kinh doanh và cá nhân kinh doanh có nhu cầu hoàn toàn được lựa chọn áp dụng Chế độ kế toán cho doanh nghiệp siêu nhỏ quy định tại Thông tư số 58/2026/TT-BTC.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-024$md$,$md$Chế độ kế toán$md$,$md$Khi hộ kinh doanh của tôi đã lựa chọn áp dụng chế độ kế toán theo Thông tư số 58/2026/TT-BTC thì tôi phải áp dụng tối thiểu trong bao lâu?$md$,$md$Bạn phải áp dụng nhất quán chế độ kế toán đã chọn trong suốt cả năm tài chính. Nếu có sự thay đổi, bạn chỉ được thực hiện thay đổi tại ngày bắt đầu kỳ kế toán năm tiếp theo.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-025$md$,$md$Chế độ kế toán$md$,$md$Hộ kinh doanh của tôi nộp thuế GTGT và thuế TNCN theo phương pháp tỷ lệ % trên doanh thu. Nếu tôi lựa chọn áp dụng Thông tư số 58/2026/TT-BTC thì tôi phải mở loại sổ kế toán nào?$md$,$md$Trường hợp hộ kinh doanh nộp thuế theo tỷ lệ % trên doanh thu, bạn chỉ cần mở và áp dụng một loại sổ duy nhất là Sổ doanh thu bán hàng hóa, dịch vụ (Mẫu số S1-DNSN).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-026$md$,$md$Chế độ kế toán$md$,$md$Sổ doanh thu bán hàng hóa, dịch vụ mẫu S1-DNSN được mở để ghi nhận những nội dung gì?$md$,$md$Sổ này dùng để ghi doanh thu bán hàng hóa, cung cấp dịch vụ trong kỳ theo từng nhóm hàng hóa, dịch vụ có cùng tỷ lệ % tính thuế nhằm làm căn cứ xác định nghĩa vụ thuế.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-027$md$,$md$Chế độ kế toán$md$,$md$Tôi đăng ký nộp thuế giá trị gia tăng theo tỷ lệ % trên doanh thu, còn thuế TNCN thì tính trên thu nhập thực tế (Doanh thu - Chi phí). Theo Thông tư số 58/2026/TT-BTC, tôi phải sử dụng hệ thống sổ sách kế toán nào?$md$,$md$Trong trường hợp này, bạn phải áp dụng hệ thống 4 sổ kế toán gồm: Sổ doanh thu bán hàng hóa, dịch vụ (Mẫu S2a-DNSN), Sổ chi tiết doanh thu, chi phí (Mẫu S2b-DNSN), Sổ chi tiết vật liệu, dụng cụ, sản phẩm, hàng hóa (Mẫu S2c-DNSN), và Sổ chi tiết tiền (Mẫu S2d-DNSN).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-028$md$,$md$Chế độ kế toán$md$,$md$Sổ chi tiết doanh thu, chi phí mẫu S2b-DNSN dùng để theo dõi những nội dung kinh tế gì?$md$,$md$Sổ này dùng để theo dõi toàn bộ doanh thu, thu nhập và các khoản chi phí phát sinh phục vụ hoạt động sản xuất kinh doanh, làm cơ sở xác định số thuế thu nhập cá nhân bạn phải nộp.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-029$md$,$md$Chế độ kế toán$md$,$md$Hộ kinh doanh của tôi đăng ký nộp thuế GTGT theo phương pháp khấu trừ và nộp thuế TNCN tính trên doanh thu bán hàng. Tôi phải mở các loại sổ kế toán nào?$md$,$md$Bạn cần mở và theo dõi 2 loại sổ: Sổ doanh thu bán hàng hóa, dịch vụ (Mẫu S3a-DNSN) và Sổ theo dõi nghĩa vụ thuế GTGT (Mẫu S3b-DNSN).$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-030$md$,$md$Chế độ kế toán$md$,$md$Để theo dõi tiền mặt tại quỹ và tiền gửi ngân hàng phục vụ kinh doanh một cách chi tiết theo Thông tư số 58/2026/TT-BTC, tôi phải sử dụng biểu mẫu nào?$md$,$md$Bạn sử dụng Sổ chi tiết tiền (Mẫu số S2d-DNSN). Sổ này được mở để theo dõi chi tiết tình hình thu, chi tiền mặt hoặc gửi vào, rút ra đối với tiền gửi ngân hàng không kỳ hạn.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-031$md$,$md$Thuế khoán$md$,$md$Tôi là hộ kinh doanh khoán bán hàng ăn. Gần đây do thi công cầu cống trước cửa nhà, tôi phải tạm dừng hoạt động kinh doanh trong 2 tháng. Mức thuế khoán của tôi có được điều chỉnh giảm không?$md$,$md$Có. Khi hộ khoán ngừng hoặc tạm ngừng hoạt động kinh doanh, cơ quan thuế sẽ tiến hành điều chỉnh lại mức thuế khoán phải nộp của bạn tương ứng với thời gian ngừng hoạt động.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-032$md$,$md$Hóa đơn$md$,$md$Năm 2026, hộ kinh doanh của tôi có doanh thu thực tế là 1,2 tỷ đồng. Tôi có bắt buộc phải sử dụng hóa đơn điện tử không?$md$,$md$Có. Theo quy định tại Nghị định số 254/2026/NĐ-CP, hộ kinh doanh có doanh thu hằng năm trên 01 tỷ đồng bắt buộc phải sử dụng hóa đơn điện tử có mã của cơ quan thuế hoặc hóa đơn điện tử khởi tạo từ máy tính tiền.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-033$md$,$md$Thuế khoán$md$,$md$Hộ kinh doanh của tôi không thực hiện chế độ kế toán và không sử dụng hóa đơn chứng từ thường xuyên. Cơ quan thuế sẽ tính thuế cho hộ tôi theo phương pháp nào?$md$,$md$Bạn sẽ nộp thuế theo phương pháp khoán thuế. Cơ quan thuế sẽ tự xác định doanh thu khoán và mức thuế khoán định kỳ hàng năm cho hộ của bạn dựa trên cơ sở dữ liệu và ý kiến tư vấn từ địa phương.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-034$md$,$md$Thuế khoán$md$,$md$Những căn cứ nào được cơ quan thuế dùng để ấn định mức thuế khoán hàng năm đối với hộ kinh doanh của tôi?$md$,$md$Mức thuế khoán được xác định căn cứ vào tờ khai tự khai của bạn, cơ sở dữ liệu quản lý của ngành thuế, và ý kiến tham vấn từ Hội đồng tư vấn thuế cấp xã, phường.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-035$md$,$md$Thuế khoán$md$,$md$Hộ kinh doanh nộp thuế khoán của tôi có được miễn thực hiện chế độ sổ sách kế toán, hóa đơn chứng từ không?$md$,$md$Có. Hộ kinh doanh nộp thuế theo phương pháp khoán thì không bắt buộc phải thực hiện chế độ sổ sách kế toán.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-036$md$,$md$Thuế khoán$md$,$md$Tôi nộp thuế khoán từ năm 2025 trở về trước. Sang năm 2026, tôi chuyển sang kê khai thuế theo phương pháp kê khai. Cơ quan thuế có dùng doanh thu mới khai năm 2026 để tính lại và truy thu số thuế khoán các năm trước của tôi không?$md$,$md$Không. Cơ quan thuế cam kết không sử dụng số liệu doanh thu kê khai mới của năm 2026 để xác định lại hoặc truy thu nghĩa vụ thuế khoán các năm trước của bạn, ngoại trừ trường hợp phát hiện có hành vi gian lận hoặc che giấu doanh thu.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-037$md$,$md$Hóa đơn$md$,$md$Doanh thu năm 2026 của hộ kinh doanh của tôi chỉ đạt 800 triệu đồng (dưới 1 tỷ đồng), nhưng một số doanh nghiệp mua hàng của tôi yêu cầu phải xuất hóa đơn điện tử. Tôi có được đăng ký sử dụng không?$md$,$md$Được. Nếu bạn có doanh thu từ 01 tỷ đồng trở xuống nhưng đáp ứng đủ điều kiện và tự nguyện muốn áp dụng, bạn hoàn toàn có thể đăng ký sử dụng hóa đơn điện tử có mã hoặc hóa đơn điện tử khởi tạo từ máy tính tiền.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-038$md$,$md$Hóa đơn$md$,$md$Tôi là hộ kinh doanh mới thành lập năm 2026. Doanh thu luỹ kế của tôi đến tháng 10/2026 vượt quá 1 tỷ đồng. Tôi phải làm thủ tục đăng ký hóa đơn điện tử trong thời hạn bao lâu?$md$,$md$Bạn có nghĩa vụ đăng ký sử dụng hóa đơn điện tử trong thời hạn tối đa 30 ngày kể từ ngày kết thúc kỳ tính thuế có doanh thu lũy kế vượt trên 01 tỷ đồng.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-039$md$,$md$Hóa đơn$md$,$md$Hộ kinh doanh nộp thuế khoán của tôi thỉnh thoảng có khách hàng doanh nghiệp yêu cầu hóa đơn lẻ cho từng đơn hàng phát sinh thì cơ quan thuế có cấp hóa đơn điện tử cho tôi không?$md$,$md$Có. Cơ quan thuế sẽ cấp hóa đơn điện tử có mã theo từng lần phát sinh (hóa đơn lẻ) cho hộ kinh doanh của bạn, và bạn phải thực hiện việc kê khai và nộp thuế đầy đủ trước khi cơ quan thuế cấp mã trên hóa đơn đó.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-040$md$,$md$Hóa đơn$md$,$md$Hộ kinh doanh của tôi ở huyện vùng cao biên giới Mèo Vạc, Hà Giang (địa bàn có điều kiện kinh tế - xã hội đặc biệt khó khăn) khi đăng ký sử dụng hóa đơn điện tử có mã của cơ quan thuế thì có được miễn phí dịch vụ không?$md$,$md$Có. Hộ kinh doanh của bạn hoạt động tại địa bàn có điều kiện kinh tế - xã hội đặc biệt khó khăn sẽ được cơ quan thuế hoặc tổ chức cung cấp dịch vụ được ủy thác cung cấp dịch vụ hóa đơn điện tử miễn phí trong thời gian 12 tháng kể từ khi sử dụng.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-041$md$,$md$Hóa đơn$md$,$md$Tôi kinh doanh dịch vụ cho thuê nhà trọ vãng lai cho khách đi du lịch. Tôi có phải lập hóa đơn điện tử khi cho thuê không?$md$,$md$Không. Hộ kinh doanh, cá nhân kinh doanh có thu nhập từ hoạt động cho thuê bất động sản thuộc đối tượng không phải sử dụng hóa đơn điện tử.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-042$md$,$md$Hóa đơn$md$,$md$Tôi làm đại lý bán vé xổ số kiến thiết đúng giá hưởng hoa hồng và đã bị công ty xổ số khấu trừ thuế tại nguồn. Tôi có phải lập hóa đơn cho khách mua vé số không?$md$,$md$Không. Bạn không phải sử dụng hóa đơn điện tử đối với hoạt động làm đại lý xổ số đã được khấu trừ thuế tại nguồn.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-043$md$,$md$Hóa đơn$md$,$md$Tôi mở cửa hàng kinh doanh gas gia dụng tại Nam Định. Tôi có bắt buộc phải kết nối hóa đơn khởi tạo từ máy tính tiền có kết nối dữ liệu với cơ quan thuế hay không?$md$,$md$Có. Cửa hàng bán lẻ trực tiếp đến người tiêu dùng (bao gồm hộ kinh doanh gas) có doanh thu hàng năm từ 01 tỷ đồng trở lên bắt buộc phải áp dụng hóa đơn điện tử khởi tạo từ máy tính tiền.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-044$md$,$md$Hóa đơn$md$,$md$Khi tôi bán xăng dầu cho khách hàng cá nhân không kinh doanh, tôi lập hóa đơn điện tử thì có bắt buộc phải ghi tên, địa chỉ và mã số thuế của khách hàng không?$md$,$md$Không. Hóa đơn điện tử bán xăng dầu cho khách hàng là cá nhân không kinh doanh thì trên hóa đơn không nhất thiết phải có các thông tin như tên, địa chỉ, mã số thuế người mua và chữ ký của người mua.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-045$md$,$md$Hóa đơn$md$,$md$Hộ kinh doanh của tôi có thuê bên thứ ba lập hóa đơn điện tử cho các hoạt động bán lẻ đồ lưu niệm của tôi. Bên nhận ủy nhiệm có phải ký số thay tôi trên hóa đơn không?$md$,$md$Có. Khi bạn ủy nhiệm cho bên thứ ba lập hóa đơn điện tử, trên hóa đơn không nhất thiết phải có chữ ký số của bạn (người bán), mà bên nhận ủy nhiệm sẽ chịu trách nhiệm ký số lên hóa đơn đó.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-046$md$,$md$Hóa đơn$md$,$md$Tôi có mua một số hóa đơn đặt in bằng giấy của cơ quan thuế trước thời điểm Nghị định 254/2026/NĐ-CP có hiệu lực thi hành và chưa sử dụng hết. Tôi có được tiếp tục sử dụng các hóa đơn giấy này nữa không?$md$,$md$Không. Kể từ ngày Nghị định số 254/2026/NĐ-CP có hiệu lực thi hành (ngày 01/07/2026), toàn bộ hóa đơn đặt in bằng giấy của cơ quan thuế sẽ hết giá trị sử dụng và bạn bắt buộc phải thực hiện tiêu hủy số hóa đơn giấy chưa sử dụng này.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-047$md$,$md$Hóa đơn$md$,$md$Tôi phát hiện hóa đơn điện tử đã gửi cho khách hàng bị ghi sai đơn giá hàng hóa nhưng mã số thuế của khách hàng vẫn chính xác. Kể từ năm 2026, tôi có được hủy hóa đơn này để lập cái mới không?$md$,$md$Không. Theo quy định mới nhất có hiệu lực, bạn không được tự ý hủy hóa đơn đã lập sai sót nữa. Thay vào đó, bạn và khách hàng phải lập văn bản thỏa thuận ghi rõ sai sót và tiến hành lập hóa đơn điều chỉnh hoặc hóa đơn thay thế.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-048$md$,$md$Hóa đơn$md$,$md$Nếu cơ quan thuế rà soát và phát hiện hóa đơn điện tử do hộ kinh doanh của tôi lập có sai sót thì tôi phải làm thế nào?$md$,$md$Khi nhận được thông báo của cơ quan thuế về việc phát hiện hóa đơn điện tử đã lập có sai sót, bạn có trách nhiệm tiến hành kiểm tra, rà soát lại thông tin và thực hiện điều chỉnh hoặc thay thế hóa đơn theo đúng quy định.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-049$md$,$md$Khai thuế$md$,$md$Tôi có một hộ kinh doanh sản xuất gạch nung tại hai địa bàn huyện khác nhau của tỉnh Hà Nam. Tôi phải thực hiện nộp thuế giá trị gia tăng như thế nào?$md$,$md$Bạn thực hiện kê khai thuế tập trung tại một nơi (trụ sở chính) của hộ kinh doanh nhưng phải phân bổ và nộp tiền thuế GTGT trực tiếp cho từng địa điểm nơi phát sinh hoạt động sản xuất kinh doanh.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-050$md$,$md$Khai thuế$md$,$md$Tôi có hoạt động cho thuê một căn hộ chung cư tại Đà Nẵng với doanh thu thuê là 150 triệu đồng/năm. Tôi đã nộp thuế đầy đủ cho cả năm. Tuy nhiên do ảnh hưởng bão lũ, hợp đồng bị chấm dứt trước hạn 6 tháng, dẫn đến doanh thu thực tế năm đó chỉ còn 75 triệu đồng. Tôi có được hoàn lại số thuế đã nộp thừa không?$md$,$md$Có. Do doanh thu thực tế cả năm của bạn sau khi rút ngắn thời hạn thuê bị giảm xuống từ 01 tỷ đồng trở xuống (mức miễn thuế), bạn thuộc diện không phải nộp thuế cả năm. Bạn được thực hiện thủ tục đề nghị hoàn trả số tiền thuế đã nộp thừa theo quy định của pháp luật quản lý thuế.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-051$md$,$md$Chế độ kế toán$md$,$md$Hộ kinh doanh nộp thuế theo phương pháp kê khai của tôi phát sinh hoạt động nhập kho vật tư từ nguồn tự sản xuất. Tôi cần sử dụng biểu mẫu chứng từ nào để làm căn cứ ghi sổ chi tiết?$md$,$md$Bạn sử dụng Phiếu nhập kho (Mẫu số 01-VT) để theo dõi và phản ánh vật tư nhập kho, làm căn cứ ghi sổ chi tiết vật liệu, dụng cụ, sản phẩm, hàng hóa.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-052$md$,$md$Khai thuế$md$,$md$Tôi kinh doanh bán vé số sỉ và lẻ nhưng không ký hợp đồng đại lý trực tiếp với doanh nghiệp xổ số mà mua đi bán lại. Tôi có được tự xác định nộp thuế theo phương pháp khoán không?$md$,$md$Có. Đối với hoạt động kinh doanh không phải là đại lý trực tiếp bán đúng giá hưởng hoa hồng của công ty xổ số, bạn thuộc diện tự kê khai nộp thuế hoặc nộp thuế theo phương pháp khoán nếu quy mô của hộ không đáp ứng tiêu chuẩn của hộ kê khai.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-053$md$,$md$Hóa đơn$md$,$md$Nếu cơ sở kinh doanh của tôi không lập hóa đơn điện tử khi bán hàng hóa cho khách hàng theo đúng quy định thì mức xử phạt hành chính đối với hành vi này là bao nhiêu?$md$,$md$Nếu hộ kinh doanh vi phạm quy định không lập hóa đơn khi bán hàng hóa, dịch vụ từ 50 số hóa đơn trở lên thì có thể bị phạt tiền từ 60.000.000 đồng đến 80.000.000 đồng, đồng thời bị buộc phải lập lại hóa đơn giao cho người mua.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-054$md$,$md$Chế độ kế toán$md$,$md$Khi ghi chép Sổ doanh thu bán hàng hóa, dịch vụ theo Thông tư 58/2026/TT-BTC, tôi có bắt buộc phải hạch toán chi tiết từng hóa đơn bán ra hay có được ghi số tổng cộng không?$md$,$md$Tùy thuộc vào nhu cầu quản trị, bạn được phép ghi nhận doanh thu theo từng hóa đơn bán ra hoặc ghi theo số tổng cộng hàng ngày kèm theo bảng kê chi tiết hóa đơn theo quy định của pháp luật.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa(qa_id,topic,question,answer,fw_group,audit_status) values($md$QA-HKD-055$md$,$md$Đăng ký thuế$md$,$md$Hộ kinh doanh có nhu cầu tạm dừng hoạt động kinh doanh thì phải gửi thông báo đến cơ quan quản lý thuế trực tiếp chậm nhất là khi nào?$md$,$md$Trong trường hợp không thuộc đối tượng phải đăng ký doanh nghiệp, bạn phải gửi thông báo tạm ngừng hoạt động kinh doanh cho cơ quan thuế quản lý trực tiếp chậm nhất là 01 ngày làm việc trước khi tạm dừng hoạt động.$md$,$md$FW-2026$md$,$md$APPROVED$md$) on conflict(qa_id) do nothing;
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-001$md$,$md$Luật quản lý thuế 2025$md$,$md$Khoản 2 Điều 33$md$,$md$Người nộp thuế đăng ký thuế trực tiếp với cơ quan thuế thì thời hạn đăng ký thuế là 10 ngày làm việc kể từ ngày sau đây: a) Được cấp giấy chứng nhận đăng ký hộ kinh doanh, giấy phép thành lập và hoạt động, giấy chứng nhận đăng ký đầu tư, quyết định thành lập;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-002$md$,$md$Luật quản lý thuế 2025$md$,$md$Điểm e Khoản 3 Điều 30$md$,$md$Mã số thuế cấp cho hộ gia đình, hộ kinh doanh, cá nhân kinh doanh là mã số thuế cấp cho cá nhân người đại diện hộ gia đình, hộ kinh doanh, cá nhân kinh doanh.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-003$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.3$md$,$md$Bổ sung quy định hộ kinh doanh thực hiện thay đổi thông tin đăng ký thuế cùng với thay đổi nội dung đăng ký hộ kinh doanh với cơ quan đăng ký kinh doanh (điểm a khoản 1 Điều 25).$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-004$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.2$md$,$md$Tại Chi cục Thuế hoặc Chi cục Thuế khu vực nơi đặt địa điểm kinh doanh cố định trong trường hợp hộ kinh doanh, cá nhân kinh doanh có địa điểm kinh doanh cố định;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-005$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.2$md$,$md$Tại Chi cục Thuế hoặc Chi cục Thuế khu vực nơi cư trú của cá nhân kinh doanh trong trường hợp cá nhân kinh doanh không có địa điểm kinh doanh cố định;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-006$md$,$md$252-ndcp.signed$md$,$md$Điểm h Khoản 1 Điều 6 (quy chiếu tại Điều 73)$md$,$md$h) Cá nhân là chủ sở hữu doanh nghiệp tư nhân, chủ sở hữu công ty trách
nhiệm hữu hạn một thành viên, thành viên hợp danh, chủ hộ kinh doanh, người
đại điện theo pháp luật của doanh nghiệp có trách nhiệm hoàn thành nghĩa vụ
nộp thuế và các nghĩa vụ có liên quan đến hỗ sơ thuế theo quy định của pháp
luật đối với doanh nghiệp, hộ kinh doanh bị cơ quan thuế thông báo không hoạt
động tại địa chỉ đã đăng ký hoặc bị cơ quan có thẩm quyền thu hồi giấy chứng$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-007$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.4$md$,$md$Hồ sơ chấm dứt hiệu lực MST là thông tin về chấm dứt hoạt động hộ kinh doanh do cơ quan đăng ký kinh doanh gửi cho cơ quan thuế qua Hệ thống thông tin quốc gia về đăng ký kinh doanh (khoản 1 Điều 29).$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-008$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.4$md$,$md$Bỏ thủ tục chấm dứt hiệu lực mã số thuế đối với địa điểm kinh doanh của hộ kinh doanh. Thay vào đó, bổ sung quy định xử lý giao dịch chấm dứt hoạt động địa điểm kinh doanh của hộ kinh doanh như sau: Cơ quan thuế quản lý khoản thu tại nơi có địa điểm kinh doanh thực hiện phối hợp với cơ quan thuế quản lý trực tiếp hộ kinh doanh, cá nhân kinh doanh để đôn đốc, xử lý nghĩa vụ thuế...$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-009$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.4$md$,$md$Sửa đổi, bổ sung quy định xử lý chấm dứt hiệu lực mã số thuế đối với hộ kinh doanh, cá nhân kinh doanh không hoạt động tại địa chỉ đã đăng ký để phù hợp với trường hợp hộ kinh doanh đăng ký thuế theo cơ chế liên thông, bỏ thông báo không hoạt động tại địa chỉ đã đăng ký đối với địa điểm kinh doanh để phù hợp với việc bỏ quy định cấp MST 13 số cho địa điểm kinh doanh của hộ kinh doanh, cá nhân kinh doanh (Điều 32).$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-010$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Mục 22.2.5$md$,$md$Cơ quan thuế xử lý khôi phục MST đối với hộ kinh doanh ngay trong ngày nhận được giao dịch khôi phục tình trạng pháp lý do cơ quan đăng ký kinh doanh gửi cho cơ quan thuế qua Hệ thống thông tin quốc gia về đăng ký kinh doanh (khoản 1 Điều 34)$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-011$md$,$md$141-ndcp.signed$md$,$md$Khoản 1 Điều 1$md$,$md$Sửa đổi cụm từ “500 triệu đồng” thành “01 tỷ đồng” tại Điều 3, Điều 4, khoản 1 Điều 8, Điều 9, Điều 10, khoản 3 Điều 11, khoản I và khoản 2 Điều 12, khoản 4 Điều 17, khoản 3 Điều 18 Nghị định số 68/2026/NĐ-CP.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-012$md$,$md$68-ndcp.signed$md$,$md$Khoản 1 Điều 10$md$,$md$a) Trường hợp có doanh thu năm từ 50 tỷ đồng trở xuống thực hiện khai thuế, nộp thuế giá trị gia tăng theo quý;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-013$md$,$md$68-ndcp.signed$md$,$md$Khoản 1 Điều 10 và Điểm b Khoản 3 Điều 8$md$,$md$Trường hợp có doanh thu năm trên 50 tỷ đồng thực hiện khai thuế, nộp thuế giá trị gia tăng theo tháng.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-014$md$,$md$68-ndcp.signed$md$,$md$Điểm a Khoản 3 Điều 8$md$,$md$Trường hợp khai thuế theo quý thì thời hạn nộp hồ sơ khai thuế chậm nhất là ngày cuối cùng của tháng đầu tiên của quý tiếp theo;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-015$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Khoản 4a Điều 42$md$,$md$Đối với hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số thì tổ chức là nhà quản lý sàn giao dịch thương mại điện tử, nhà quản lý nền tảng số có chức năng thanh toán (bao gồm cả tổ chức trong nước và nước ngoài) và các tổ chức có hoạt động kinh tế số khác theo quy định của Chính phủ thực hiện khấu trừ, nộp thuế thay, kê khai số thuế đã khấu trừ cho hộ kinh doanh, cá nhân kinh doanh.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-016$md$,$md$68-ndcp.signed$md$,$md$Điểm b Khoản 4 Điều 8$md$,$md$Hộ kinh doanh, cá nhân kinh doanh bao gồm cả kinh doanh thương mại điện tử có nhiều địa điểm kinh doanh (cửa hàng) hoạt động trên cùng địa bàn một tỉnh, thành phố hoặc khác tỉnh, thành phố, thực hiện khai thuế tổng hợp chung cho các địa điểm kinh doanh trên 01 hồ sơ khai thuế để nộp cho cơ quan thuế quản lý trực tiếp trụ sở của hộ kinh doanh, cá nhân kinh doanh... Hộ kinh doanh, cá nhân kinh doanh thực hiện nộp thuế cho từng địa điểm kinh doanh.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-017$md$,$md$68-ndcp.signed$md$,$md$Điểm c Khoản 4 Điều 8$md$,$md$Đối với hộ kinh doanh, cá nhân kinh doanh chỉ có hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số và không có địa điểm kinh doanh thì thực hiện kê khai, nộp thuế tại cơ quan thuế quản lý địa bàn nơi hộ kinh doanh, cá nhân kinh doanh cư trú: nơi ở hiện tại; nơi tạm trú hoặc nơi thường trú;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-018$md$,$md$68-ndcp.signed$md$,$md$Khoản 7 Điều 8$md$,$md$Tổ chức thuê bất động sản của cá nhân mà trong hợp đồng thuê bất động sản có thỏa thuận bên đi thuê là người khai thuế thay, nộp thuế thay... có trách nhiệm khai thuế thay, nộp thuế thay cho cá nhân khi chi trả thu nhập cho cá nhân.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-019$md$,$md$68-ndcp.signed$md$,$md$Khoản 3 Điều 4 (kết hợp sửa đổi mức trừ tại Khoản 1 Điều 1 NĐ 141/2026/NĐ-CP)$md$,$md$áp dụng mức trừ 500 triệu đồng trước khi tính thuế thu nhập cá nhân đối với
một hoặc một số ngành, nghề kinh doanh hoặc địa điểm kinh doanh do cá nhân
lựa chọn theo phương án có lợi nhất, nhưng tổng mức trừ không vượt quá 500
triệu đồng trong một năm đối với doanh thu của toàn bộ hoạt động kinh doanh$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-020$md$,$md$68-ndcp.signed$md$,$md$Khoản 1 Điều 9 (kết hợp sửa đổi mức quy chiếu NĐ 141/2026/NĐ-CP)$md$,$md$Hộ kinh doanh, cá nhân kinh doanh bắt đầu hoạt động sản xuất, kinh
doanh trong 06 tháng đầu năm nếu có doanh thu thực tế từ 500 triệu đồng trở
xuống thì thực hiện thông báo doanh thu thực tế phát sinh kể từ khi bắt đầu hoạt
động sản xuất, kinh doanh đến hết ngày 30 tháng 6 với cơ quan thuế quản lý
trực tiếp chậm nhất là ngày 31 tháng 7$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-021$md$,$md$68-ndcp.signed$md$,$md$Khoản 1 Điều 9$md$,$md$Trường hợp hộ kinh doanh, cá nhân kinh doanh bắt đầu hoạt động sản xuất, kinh doanh trong 06 tháng cuối năm nếu có doanh thu thực tế từ [01 tỷ đồng] trở xuống thì thực hiện thông báo doanh thu thực tế phát sinh chậm nhất là ngày 31 tháng 01 của năm dương lịch tiếp theo.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-022$md$,$md$68-ndcp.signed$md$,$md$Khoản 2 Điều 9 (kết hợp sửa đổi mức quy chiếu NĐ 141/2026/NĐ-CP)$md$,$md$Hộ kinh doanh, cá nhân kinh doanh mới bắt đầu hoạt động sản xuất, kinh doanh, khi có doanh thu lũy kế trên [01 tỷ đồng] thì thực hiện khai thuế theo quý theo quy định tại Điều 10 Nghị định này kể từ quý phát sinh doanh thu trên [01 tỷ đồng].$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-023$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Khoản 2 Điều 2$md$,$md$Hộ kinh doanh, cá nhân kinh doanh nếu có nhu cầu thì được lựa chọn áp dụng Thông tư này để thực hiện công tác kế toán.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-024$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Khoản 4 Điều 4$md$,$md$Trường hợp hộ kinh doanh, cá nhân kinh doanh lựa chọn áp dụng chế độ kế toán theo Thông tư này thì phải áp dụng nhất quán trong một năm tài chính. Việc thay đổi chế độ kế toán áp dụng chỉ được thực hiện tại ngày bắt đầu kỳ kế toán năm tiếp theo.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-025$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Khoản 2.1 Mục 2 Điều 5$md$,$md$Trường hợp này, doanh nghiệp siêu nhỏ áp dụng Sổ doanh thu bán hàng hóa, dịch vụ (Mẫu số S1-DNSN) để ghi doanh thu bán hàng hóa, dịch vụ.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-026$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Điểm b Khoản 2.2 Mục 2 Điều 5$md$,$md$Sổ này được mở để ghi doanh thu bán hàng hóa, cung cấp dịch vụ trong kỳ theo từng nhóm hàng hóa, dịch vụ, ngành nghề có cùng tỷ lệ % tính thuế GTGT hoặc cùng tỷ lệ % tính thuế TNDN.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-027$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Khoản 2.1 Mục 2 Điều 6$md$,$md$Trường hợp này, doanh nghiệp siêu nhỏ áp dụng các số kế toán theo
danh mục sau đây$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-028$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Điểm b2 Khoản 2.2 Mục 2 Điều 6$md$,$md$Sổ này được mở để theo dõi doanh thu, thu nhập và chi phí phát sinh trong hoạt động sản xuất, kinh doanh và hoạt động khác của doanh nghiệp siêu nhỏ.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-029$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Khoản 2.1 Mục 2 Điều 7$md$,$md$Trường hợp này, doanh nghiệp siêu nhỏ áp dụng các sổ kế toán theo danh mục sau đây: 1. Sổ doanh thu bán hàng hóa, dịch vụ Mẫu số S3a-DNSN; 2. Sổ theo dõi nghĩa vụ thuế GTGT Mẫu số S3b-DNSN$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-030$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Điểm d2 Khoản 2.2 Mục 2 Điều 6$md$,$md$Sổ này được mở để theo dõi tình hình thu, chi bằng tiền mặt hoặc tiền gửi không kỳ hạn (tiền gửi để thanh toán) trong tài khoản của doanh nghiệp siêu nhỏ tại các ngân hàng và tổ chức cung ứng dịch vụ thanh toán theo quy định của pháp luật.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-031$md$,$md$CD3 Thuế 2025$md$,$md$Mục 6.2.5.2 (điểm b)$md$,$md$Trường hợp hộ khoán đã được thông báo số thuế từ đầu năm nhưng trong năm ngừng hoặc tạm ngừng kinh doanh thì cơ quan thuế thực hiện điều chỉnh số thuế phải nộp...$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-032$md$,$md$254-ndcp.signed$md$,$md$Điểm đ Khoản 1 Điều 6$md$,$md$Hộ kinh doanh, cá nhân kinh doanh có doanh thu năm trên 01 tỷ đồng hoặc hộ kinh doanh, cá nhân kinh doanh bán tài sản phải đăng ký quyền sở hữu, quyền sử dụng thì phải áp dụng hóa đơn điện tử có mã của cơ quan thuế, hóa đơn điện tử khởi tạo từ máy tính tiền có kết nối dữ liệu với cơ quan thuế.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-033$md$,$md$141-ndcp.signed$md$,$md$Khoản 1 Điều 51$md$,$md$Cơ quan thuế xác định số tiền thuế phải nộp theo phương pháp khoán thuế (sau đây gọi là mức thuế khoán) đối với trường hợp hộ kinh doanh, cá nhân kinh doanh không thực hiện hoặc thực hiện không đầy đủ chế độ kế toán, hóa đơn, chứng từ, trừ trường hợp quy định tại khoản 5 Điều này.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-034$md$,$md$20171205-TT-111-2013-TT-BTC$md$,$md$Khoản 2 Điều 51$md$,$md$Cơ quan thuế căn cứ vào tài liệu kê khai của hộ kinh doanh, cá nhân kinh doanh, cơ sở dữ liệu của cơ quan thuế, ý kiến của Hội đồng tư vấn thuế xã, phường, thị trấn để xác định mức thuế khoán.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-035$md$,$md$20171205-TT-111-2013-TT-BTC$md$,$md$Mục 6.2.5.2.b$md$,$md$Hộ kinh doanh, cá nhân kinh doanh nộp thuế theo phương pháp khoán (Hộ khoán) không phải thực hiện chế độ kế toán.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-036$md$,$md$68-ndcp.signed$md$,$md$Khoản 5 Điều 17$md$,$md$khi chuyển sang thực hiện kê khai thuế kể từ ngày 01 tháng 01 năm 2026,
cơ quan thuế không sử dụng doanh thu khai thuế năm 2026 để xác định lại
nghĩa vụ thuế các năm trước, không xử phạt vi phạm hành chính đối với các
nghĩa vụ thuế đã thực hiện theo phương pháp khoán$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-037$md$,$md$254-ndcp.signed$md$,$md$Đoạn cuối Khoản 1 Điều 6$md$,$md$Hộ kinh doanh, cá nhân kinh doanh không thuộc trường hợp sử dụng hóa đơn điện tử mà có nhu cầu sử dụng hóa đơn điện tử thì đăng ký sử dụng hóa đơn điện tử có mã của cơ quan thuế hoặc hóa đơn điện tử khởi tạo từ máy tính tiền có kết nối dữ liệu với cơ quan thuế.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-038$md$,$md$141-ndcp.signed$md$,$md$Điểm c Khoản 2 Điều 1$md$,$md$Hộ kinh doanh, cá nhân kinh doanh đăng ký sử dụng hóa đơn điện tử trong thời gian 30 ngày kể từ ngày cuối cùng của kỳ tính thuế có doanh thu lũy kế trên 01 tỷ đồng.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-039$md$,$md$Luatquanlythue2025VBHN29.$md$,$md$Khoản 4 Điều 91$md$,$md$Hộ kinh doanh, cá nhân kinh doanh không đáp ứng điều kiện phải sử dụng hóa đơn điện tử có mã của cơ quan thuế quy định tại khoản 1 và khoản 3 Điều này nhưng cần có hóa đơn để giao cho khách hàng hoặc trường hợp doanh nghiệp, tổ chức kinh tế, tổ chức khác được cơ quan thuế chấp nhận cấp hóa đơn điện tử để giao cho khách hàng thì được cơ quan thuế cấp hóa đơn điện tử có mã theo từng lần phát sinh và phải khai thuế, nộp thuế trước khi cơ quan thuế cấp hóa đơn điện tử theo từng lần phát sinh.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-040$md$,$md$254-ndcp.signed$md$,$md$Khoản 1 Điều 11$md$,$md$Doanh nghiệp nhỏ và vừa, hợp tác xã, liên hiệp hợp tác xã, hộ kinh doanh, cá nhân kinh doanh tại địa bàn có điều kiện kinh tế - xã hội khó khăn, địa bàn có điều kiện kinh tế - xã hội đặc biệt khó khăn thuộc trường hợp sử dụng hóa đơn điện tử được miễn phí dịch vụ trong thời gian 12 tháng kể từ khi sử dụng hóa đơn điện tử.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-041$md$,$md$254-ndcp.signed$md$,$md$Khoản 2 Điều 7$md$,$md$Hộ kinh doanh, cá nhân kinh doanh có thu nhập từ hoạt động cho thuê bất động sản; thu nhập từ hoạt động cung cấp sản phẩm và dịch vụ nội dung thông tin số về giải trí, trò chơi điện tử, phim số, ảnh số, nhạc số, quảng cáo số - cho tổ chức, cá nhân ở nước ngoài.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-042$md$,$md$254-ndcp.signed$md$,$md$Khoản 3 Điều 7$md$,$md$Hộ kinh doanh, cá nhân kinh doanh làm đại lý xổ số, đại lý bảo hiểm, đại lý bán hàng đa cấp mà doanh nghiệp xổ số, bảo hiểm, bán hàng đa cấp đã khấu trừ thuế theo quy định pháp luật quản lý thuế.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-043$md$,$md$254-ndcp.signed$md$,$md$Điểm c Khoản 1 Điều 6 (quy chiếu sang Mẫu 01/TB-NSD và Khoản 8 Điều 1 Nghị định 70/2025/NĐ-CP)$md$,$md$đ) Hộ kinh doanh, cá nhân kinh doanh có doanh thu năm trên 01tỷ đồng
hoặc hộ kinh doanh, cá nhân kinh doanh bán tài sản phải đăng ký quyền sở hữu,
quyền sử dụng thì phải áp dụng hóa đơn điện tử có mã của cơ quan thuế, hóa
đơn điện tử khởi tạo từ máy tính tiền có kết nối dữ liệu với cơ quan thuế.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-044$md$,$md$254-ndcp.signed$md$,$md$Khoản 15 Điều 10 (quy chiếu sang điểm c Khoản 14)$md$,$md$đối với hóa đơn điện tử bán xăng dầu cho khách hàng là cá nhân không kinh doanh thì không nhất thiết phải có các chỉ tiêu: tên, địa chỉ, mã số thuế người mua, chữ ký số của người mua.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-045$md$,$md$254-ndcp.signed$md$,$md$Khoản 15 Điều 10 (quy chiếu sang điểm m Khoản 14)$md$,$md$đối với hóa đơn điện tử ủy nhiệm thì trên hóa đơn không nhất thiết phải có chữ ký số của người bán, bên nhận ủy nhiệm có trách nhiệm ký số trên hóa đơn điện tử được ủy nhiệm lập;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-046$md$,$md$254-ndcp.signed$md$,$md$Khoản 3 Điều 44$md$,$md$3. Kế từ ngày Nghị định này có hiệu lực thi hành, hóa đơn đặt in của cơ
quan thuế hết giá trị sử dụng. Cơ quan thuế, tổ chức kinh tế, tổ chức, hộ kinh
doanh, cá nhân kinh doanh sử dụng hóa đơn đặt in của cơ quan thuế chưa sử
dụng hết phải thực hiện tiêu hủy hóa đơn đặt in của cơ quan thuế theo trình tự,
thủ tục do Bộ trưởng Bộ Tài chính quy định.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-047$md$,$md$Sổ tay thuế _Cục Thuế _ T9 năm 2025$md$,$md$Khoản 13 Điều 1 (quy chiếu tại Mục 2.9 Sổ tay thuế)$md$,$md$quy định mới bãi bỏ việc hủy hóa đơn lập sai sót, thay vào đó tất cả đều xử lý bằng lập hóa đơn điều chỉnh hoặc thay thế.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-048$md$,$md$1225_BTC đối thoại người nộp thuế_TL Thuế$md$,$md$Điểm b Khoản 13 Điều 1 (quy chiếu tại Mục 11.1.7)$md$,$md$Trường hợp cơ quan thuế phát hiện hóa đơn điện tử có mã của cơ quan thuế hoặc hóa đơn điện tử không có mã của cơ quan thuế đã lập sai thì cơ quan thuế thông báo cho người bán để người bán kiểm tra nội dung sau và có trách nhiệm rà soát theo thông báo của cơ quan thuế và thực hiện điều chỉnh, thay thế hóa đơn theo quy định.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-049$md$,$md$141-ndcp.signed$md$,$md$Khoản 4 Điều 8$md$,$md$Trường hợp hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thu nhập tính thuế nhân (x) thuế suất thì hộ kinh doanh, cá nhân kinh doanh kê khai doanh thu từng địa điểm kinh doanh và thực hiện nộp thuế giá trị gia tăng theo từng địa điểm kinh doanh, nộp thuế thu nhập cá nhân tại trụ sở chính;$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-050$md$,$md$68-ndcp.signed$md$,$md$Khoản 2 Điều 12 (kết hợp sửa đổi mức miễn thuế tại Khoản 1 Điều 1 NĐ 141/2026/NĐ-CP)$md$,$md$Trường hợp hộ kinh doanh, cá nhân kinh doanh đã nộp thuế giá trị gia tăng, thuế thu nhập cá nhân đối với hoạt động kinh doanh nhưng có doanh thu thực tế phát sinh của năm từ [01 tỷ đồng] trở xuống thì thực hiện xử lý bù trừ, hoàn trả, hoàn trả kiêm bù trừ thu ngân sách theo quy định của pháp luật quản lý thuế đối với số thuế nộp thừa.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-051$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Điểm b Khoản 2.3 Mục 2 Điều 9$md$,$md$Chứng từ này được lập để theo dõi và phản ánh vật liệu, dụng cụ, sản
phẩm, hàng hoá nhập kho do mua ngoài, tự sản xuất, thuê ngoài gia công chế
biến, nhận góp vốn hoặc thừa phát hiện trong kiểm kê làm căn cứ ghỉ số chỉ tiết
vật liệu, dụng cụ, sản phẩm, hàng hóa, thanh toán tiền hàng, xác định trách
nhiệm với người có liên quan và ghi số kế toán.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-052$md$,$md$254-ndcp.signed$md$,$md$Khoản 3 Điều 7$md$,$md$Hộ kinh doanh, cá nhân kinh doanh làm đại lý xổ số, đại lý bảo hiểm, đại lý bán hàng đa cấp mà doanh nghiệp xổ số, bảo hiểm, bán hàng đa cấp đã khấu trừ thuế theo quy định pháp luật quản lý thuế.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-053$md$,$md$254-ndcp.signed$md$,$md$Khoản 15 Điều 1 (sửa đổi Điều 24 Nghị định 125/2020/NĐ-CP)$md$,$md$Phạt tiền từ 60.000.000 đồng đến 80.000.000 đồng trong trường hợp không lập hóa đơn khi bán hàng hóa, cung cấp dịch vụ theo quy định từ 50 số hóa đơn trở lên.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-054$md$,$md$58-ttbtc-ve-hd-che-do-ke-toan-cho-dn-sieu-nho_295202611$md$,$md$Điểm c Khoản 2.2 Mục 2 Điều 5$md$,$md$Tùy theo yêu cầu quản lý, doanh nghiệp siêu nhỏ có thể ghi doanh thu theo từng hóa đơn, chứng từ hoặc theo số tổng cộng kèm theo bảng dữ liệu chi tiết về hóa đơn, chứng từ theo quy định của pháp luật.$md$);
insert into thue.qa_legal_basis(qa_id,doc_id,clause,verbatim_quote) values($md$QA-HKD-055$md$,$md$Luatquanlythue2025VBHN29.$md$,$md$Khoản 2 Điều 37$md$,$md$Tổ chức, hộ kinh doanh, cá nhân kinh doanh không thuộc diện đăng ký kinh doanh thì thực hiện thông báo đến cơ quan thuế quản lý trực tiếp chậm nhất là 01 ngày làm việc trước khi tạm ngừng hoạt động, kinh doanh hoặc tiếp tục hoạt động, kinh doanh trước thời hạn đã thông báo để thực hiện quản lý thuế.$md$);
